// ============================================================
// 1. بيانات الموسوعة (التجريبية)
// ============================================================
const encyclopediaData_Part1_A = [
    // --- حرف A (الدفعة الأولى من الكتاب الأول) ---
    { term: "المطلق", definition: "المطلق (Absolu) — ما استغنى عن كل علاقة بغيره، وما يوجد لذاته وبذاته. وفي الفلسفة النقدية، هو ما يتجاوز النسبية والشروط التجريبية." },
    { term: "المطلقية", definition: "المطلقية (Absolutisme) — المذهب السياسي القائل بتركز السلطة المطلقة غير المقيدة، أو المذهب الفلسفي القائل بوجود حقائق وقيم مطلقة لا تتغير." },
    { term: "التجريد", definition: "التجريد (Abstraction) — العملية العقلية التي يتم من خلالها فصل صفة أو علاقة عن الموضوع العيني الذي تقوم به لتصبح موضوعاً مستقلاً للتفكير." },
    { term: "المجرّد", definition: "المجرّد (Abstrait) — ما هو معزول عن الواقع العيني المحسوس ولا يُدرك إلا بالذهن، في مقابل الملموس أو العيني (Concret)." },
    { term: "العبث", definition: "العبث / المحال (Absurde) — ما يناقض مبادئ العقل والمنطق، أو ما يفتقر إلى أي معنى أو غاية مبررة في الوجود." },
    { term: "الخلف (البرهان بالخلف)", definition: "البرهان بالخلف (Réduction à l'absurde) — استدلال منطقي يثبت صحة قضية ما عبر إثبات أن نقيضها يؤدي إلى تناقض أو نتيجة محالة." },
    { term: "التعسف / إساءة الاستعمال", definition: "التعسف (Abus) — استخدام الحق أو السلطة أو اللفظ خارج حدوده المشروعة أو المنطقية." },
    { term: "الأكاديمية", definition: "الأكاديمية (Académie) — المدرسة الفلسفية التي أسسها أفلاطون في أثينا، وتُطلق تاريخياً على مراحل تطور الأفلاطونية (القديمة، الوسطى، الجديدة)." },
    { term: "القبول / التسليم", definition: "القبول (Acceptation) — موافقة الذهن على قضية أو قاعدة، أو المعنى الاصطلاحي الخاص الذي يُؤخذ به اللفظ في سياق معين." },
    { term: "العَرَض", definition: "العَرَض (Accident) — الصفة غير الجوهرية التي تلحق بالشيء ويمكن أن تزول دون أن تتغير ماهيته (في مقابل الجوهر Substance)." },
    { term: "العَرَضية", definition: "العَرَضية (Accidentalité) — صفة ما يقع بالاتفاق أو الصدفة دون ضرورة جوهرية أو قانون حتمي." },
    { term: "التكيف", definition: "التكيف / الملاءمة (Adaptation) — تعديل الكائن الحي لبنيته أو سلوكه ليتوافق مع شروط البيئة، أو تلاؤم الفكر مع الواقع." },
    { term: "المتطابق / الملائم", definition: "المتطابق (Adéquat) — الفكرة أو المعرفة التي تطابق موضوعها تماماً وتستوعب جميع خصائصه (كما عند سبينوزا وليبنتز)." },
    { term: "المطابقة", definition: "المطابقة (Adéquation) — التوافق التام بين الفكر والواقع، وهو التعريف الكلاسيكي للحقيقة." },
    { term: "الالتصاق / الإذعان", definition: "الإذعان العقلي (Adhésion) — انضمام الذهن وموافقته الواعية على حكم أو عقيدة أو مبدأ." },
    { term: "المتاخمة / التجاور", definition: "التجاور (Adjacence) — العلاقة المكانية أو المنطقية بين عنصرين متلاصقين دون وسيط." },
    { term: "الجماليات / الاستاطيقا", definition: "الاستاطيقا / علم الجمال (Esthétique / Aesthetica) — العلم الباحث في شروط الجمال والحكم الذوقي، أو نظرية الإدراك الحسي عند كانط." },
    { term: "الانفعال", definition: "الانفعال (Affect) — كل حالة وجدانية أولية من لذة أو ألم أو رغبة تطرأ على النفس." },
    { term: "التأثر / الانفعالية", definition: "الانفعالية (Affectivité) — مجموع الظواهر الوجدانية والعاطفية في مقابل الوظائف العقلية والمعرفية." },
    { term: "الانتساب / البنوة الفكرية", definition: "الانتساب الفكري (Affiliation) — الارتباط التاريخي والمنهجي بين مذهب فلسفي ومصادره السابقة." },
    { term: "الإيجاب / الإثبات", definition: "الإثبات (Affirmation) — الحكم المنطقي الذي يقرر وجود علاقة بين الموضوع والمحمول (في مقابل السلب أو النفي)." },
    { term: "الفاعل / العامل", definition: "الفاعل (Agent) — الذات أو القوة التي يصدر عنها الفعل وتُحدث التغيير (مثل العقل الفعال عند أرسطو)." },
    { term: "الفاعلية / الفعل", definition: "الفاعلية (Agir) — ممارسة النشاط والتأثير في العالم أو في الذات، مقابل الانفعال والتلقي." },
    { term: "اللاأدرية", definition: "اللاأدرية (Agnosticisme) — المذهب الفلسفي القائل بأن العقل البشري عاجز عن معرفة المطلق أو ما وراء الطبيعة لعدم إمكانية إخضاعهما للتجربة." },
    { term: "أليثيا (الحقيقة)", definition: "أليثيا (Aléthéia) — المصطلح اليوناني للحقيقة بوصفها انكشافاً وظهوراً للوجود وخروجاً من الخفاء." },
    { term: "الخوارزمية", definition: "الخوارزمية (Algorithme) — نسق من القواعد والعمليات الرمزية المنظمة لحل مسألة منطقية أو رياضية بخطوات محددة." },
    { term: "الاستلاب / الاغتراب", definition: "الاستلاب (Aliénation) — فقدان الذات لهويتها وحريتها وتحولها إلى شيء غريب عن نفسها (في الفلسفة الهيجلية والماركسية والطب النفسي)." },
    { term: "الغيرية / التغاير", definition: "الغيرية (Altérité) — صفة ما هو آخر ومختلف عن الذات؛ وهي المبدأ المقابل للهوية." },
    { term: "الإيثار", definition: "الإيثار (Altruisme) — المبدأ الأخلاقي الداعي إلى تفضيل مصلحة الآخرين ومحبتهم لذاتهم (مصطلح صاغه أوغست كونت مقابل الأنانية)." },
    { term: "الغموض / الالتباس", definition: "الالتباس (Ambiguïté) — احتمال اللفظ أو الموقف لأكثر من معنى أو تأويل متعارض." },
    { term: "النفس / الروح", definition: "النفس (Âme) — المبدأ الحيوي والروحي المحرك للكائن الحي ومقر الوعي والفكر في الفلسفة الكلاسيكية." },
    { term: "اللاأخلاقية", definition: "اللاأخلاقية (Amoralisme) — الموقف الذي ينكر قيمة المعايير الأخلاقية أو يضع نفسه خارج نطاق التمييز بين الخير والشر." },
    { term: "التماثل / القياس التمثيلي", definition: "التماثل (Analogie) — تشابه العلاقات بين شيئين مختلفين، ويُستخدم كاستدلال لتفسير المجهول بالمعلوم." },
    { term: "التحليل", definition: "التحليل (Analyse) — المنهج العقلي الذي يفكك الكل المركب إلى عناصره البسيطة لفهم بنيته أو رد النتائج إلى مبادئها." },
    { term: "التحليلي (الحكم)", definition: "الحكم التحليلي (Jugement analytique) — حكم يكون فيه المحمول متضمناً في مفهوم الموضوع ذاته ولا يضيف معرفة جديدة (عند كانط)." },
    { term: "التحليل النفسي", definition: "التحليل النفسي (Psychanalyse / Analyse psychologique) — منهج استكشاف العمليات النفسية اللاواعية وتأويلها." },
    { term: "الفوضوية / اللاسلطوية", definition: "اللاسلطوية (Anarchie) — المذهب السياسي الداعي إلى إلغاء الدولة وكل سلطة قسرية وإقامة مجتمع قائم على التعاون الحر." },
    { term: "الأنجلوسكسونية (الفلسفة)", definition: "التقليد الفلسفي التجريبي والتحليلي السائد في الفكر الإنجليزي والأمريكي." },
    { term: "الألم / الوجع", definition: "الألم (Angoisse / Douleur) — القلق الوجودي العميق أمام الحرية والعدم (عند كيركغور وهيدغر وسارتر) أو الإحساس المؤلم." },
    { term: "الإحيائية", definition: "الإحيائية (Animisme) — الاعتقاد بأن كل ظواهر الطبيعة والكائنات مسكونة بأرواح أو قوى حية واعية." },
    { term: "الشذوذ", definition: "الشذوذ (Anomalie) — الانحراف عن القاعدة الطبيعية أو القانون العام دون أن يعني بالضرورة مرضاً." },
    { term: "اللامعيارية / الأنوميا", definition: "الأنوميا (Anomie) — حالة تفكك القواعد والقيم الأخلاقية والاجتماعية داخل المجتمع (مفهوم دوركايمي)." },
    { term: "الاستباق / التوقع", definition: "الاستباق (Anticipation) — حكم يسبق التجربة المنظمة (كما في استباقات الطبيعة عند فرنسيس بيكون)." },
    { term: "التناقض الظاهري / النقيضة", definition: "النقيضة / الأنتينوميا (Antinomie) — تعارض منطقي بين قضيتين متناقضتين يمكن البرهنة على كل منهما بأدلة عقلية متكافئة (نقيضات العقل الخالص عند كانط)." },
    { term: "التقابل / التضاد", definition: "التضاد (Antithèse) — القضية المضادة للأطروحة في الحركة الجدلية، أو التنافر البلاغي والمنطقي بين فكرتين." },
    { term: "المركزية البشرية", definition: "المركزية البشرية (Anthropocentrisme) — التصور الذي يجعل الإنسان مركز الكون والغاية النهائية لكل ما في الطبيعة." },
    { term: "التشبيه الإنساني", definition: "التشبيه الإنساني (Anthropomorphisme) — إضفاء الصفات والانفعالات البشرية على الله أو على قوى الطبيعة." },
    { term: "الأنثروبولوجيا", definition: "الأنثروبولوجيا (Anthropologie) — العلم الشامل للإنسان في أبعاده البيولوجية والثقافية والفلسفية." },
    { term: "اللامبالاة الرواقية", definition: "الأباثيا / التحرر من الانفعال (Apathie) — حالة الصفاء العقلي الناجمة عن السيطرة التامة على الأهواء والانفعالات عند الرواقيين." },
    { term: "الإدراك الواعي / التبصر", definition: "الإدراك الواعي (Aperception) — الوعي الذاتي المصاحب للإدراك، أو النشاط التركيبي للعقل في توحيد المعطيات (عند ليبنتز وكانط)." },
    { term: "اللايقين / الحيرة", definition: "الأبوريا / الإشكال المستعصي (Aporie) — مأزق منطقي أو مسألة فلسفية تبدو بلا حل لتكافؤ الحجج المتعارضة فيها." },
    { term: "بعدي (معرفة بعدية)", definition: "بعدي (A posteriori) — كل معرفة أو حكم يستند إلى التجربة الحسية ويتوقف عليها في إثبات صدقه." },
    { term: "قبلي (معرفة قبلية)", definition: "قبلي (A priori) — كل مبدأ أو معرفة مستقلة عن التجربة الحسية وسابقة عليها منطقياً، وتتسم بالضرورة والكلية (عند كانط)." },
    { term: "المظهر / الظاهر", definition: "المظهر (Apparence) — الصورة التي يبدو عليها الشيء للحواس وقد تخالف حقيقته الباطنة." },
    { term: "الميل / النزوع", definition: "النزوع (Appétition) — الميل الداخلي الذي يدفع الكائن أو المونادة للانتقال من إدراك إلى آخر (عند ليبنتز)." },
    { term: "التطبيق", definition: "التطبيق (Application) — إخضاع القواعد النظرية أو المبادئ المجردة لحالات جزئية وعملية." },
    { term: "التقدير / الحكم القيمي", definition: "التقدير (Appréciation) — الحكم الذي يحدد قيمة الشيء الأخلاقية أو الجمالية في مقابل حكم الواقع." },
    { term: "التعلم", definition: "التعلم (Apprentissage) — اكتساب معارف أو مهارات أو أنماط سلوكية جديدة عبر التجربة والتدريب." },
    { term: "الاستحسان", definition: "الاستحسان (Approbation) — الحكم الأخلاقي الإيجابي المؤيد لفعل أو سلوك ما." },
    { term: "التقريب", definition: "التقريب (Approximation) — الاقتراب المتدرج من الحقيقة أو القيمة الدقيقة دون بلوغها بصورة مطلقة (مفهوم أساسي في الإبستمولوجيا)." },
    { term: "الاستعداد / الأهلية", definition: "الاستعداد (Aptitude) — القابلية الفطرية أو المكتسبة للقيام بنشاط عقلي أو حركي معين." },
    { term: "الاعتباطي", definition: "الاعتباطي (Arbitraire) — ما يصدر عن محض الإرادة أو الصدفة دون ضرورة عقلية أو طبيعية (مثل اعتباطية العلامة اللغوية)." },
    { term: "حرية الاختيار", definition: "حرية الاختيار (Libre arbitre) — قدرة الإرادة الإنسانية على الاختيار بين المتقابلات دون حتمية مسبقة." },
    { term: "النموذج الأصلي", definition: "النموذج الأصلي (Archétype) — المثال الأبدي الأول للأشياء (عند أفلاطون) أو الصور الفطرية في اللاوعي الجمعي (عند يونغ)." },
    { term: "المبدأ الأول / الأرخيه", definition: "المبدأ الأول (Archè) — الأصل الجوهري والعنصر الأساسي الذي نشأ منه الكون في الفلسفة اليونانية ما قبل سقراط." },
    { term: "الحجة", definition: "الحجة (Argument) — الدليل المنطقي أو الخطابي المقدم لإثبات صحة دعوى أو دحضها." },
    { term: "الحجاج", definition: "الحجاج (Argumentation) — فن بناء الحجج وترتيبها لإقناع العقل أو الجمهور." },
    { term: "الأرسطية", definition: "الأرسطية (Aristotélisme) — المنظومة الفلسفية والمنطقية المستندة إلى تعاليم أرسطو وشراحه." },
    { term: "الأرستقراطية", definition: "الأرستقراطية (Aristocratie) — نظام الحكم الذي تتولاه النخبة الفاضلة أو الطبقة الممتازة اجتماعياً وفكرياً." },
    { term: "علم الحساب", definition: "علم الحساب (Arithmétique) — العلم الرياضي الباحث في الأعداد وخصائصها والعمليات المجردة عليها." },
    { term: "الفن", definition: "الفن (Art) — كل نشاط إنساني منظم يهدف إلى إنتاج الجمال أو تحقيق غاية عملية وفق قواعد متقنة." },
    { term: "الاصطناعي", definition: "الاصطناعي (Artificiel) — ما هو من صنع الإنسان وتدبيره، في مقابل ما هو طبيعي وتلقائي." },
    { term: "الزهد", definition: "الزهد (Ascétisme) — مذهب أخلاقي وروحي يدعو إلى كبح الشهوات والانفصال عن ملذات الجسد لسمو الروح." },
    { term: "الجانب / المظهر", definition: "الجانب (Aspect) — الزاوية المعينة التي يظهر بها الموضوع للذهن أو الملاحظة." },
    { term: "التقرير / الجزم", definition: "التقرير (Assertion) — طرح قضية بوصفها صادقة بصورة قاطعة، سواء أكانت بديهية أم مبرهنة." },
    { term: "التمثل الغذائي / الاستيعاب", definition: "الاستيعاب (Assimilation) — دمج العناصر الخارجية في بنية الكائن الحي أو دمج المعارف الجديدة في البنيات الذهنية القائمة." },
    { term: "التداعي", definition: "التداعي (Association) — الترابط التلقائي بين الأفكار أو الصور الذهنية نتيجة التشابه أو التضاد أو الاقتران الزماني والمكاني." },
    { term: "التداعية", definition: "التداعية (Associationnisme) — المذهب النفسي الذي يفسر جميع العمليات العقلية العليا عبر قوانين تداعي الأفكار البسيطة." },
    { term: "الافتراض / المسلمة", definition: "الافتراض (Assomption) — اتخاذ قضية ما كنقطة انطلاق مؤقتة للاستدلال." },
    { term: "اليقين الذاتي / الثقة", definition: "الثقة / الاطمئنان (Assurance) — الشعور النفسي القوي بصحة الحكم أو نجاعة الفعل." },
    { term: "الطمأنينة / الأتاراكسيا", definition: "الأتاراكسيا / طمأنينة النفس (Ataraxie) — حالة السكينة المطلقة والتحرر من القلق والخوف، وهي غاية الحكيم عند الأبيقوريين والشكاك." },
    { term: "الإلحاد", definition: "الإلحاد (Athéisme) — المذهب الفلسفي القائل بإنكار وجود إله خالق أو مبدأ متعالٍ يدير الكون." },
    { term: "الذرة", definition: "الذرة (Atome) — الجزء المادي الدقيق غير القابل للانقسام الذي تتألف منه الأجسام في الفلسفة الذرية القديمة." },
    { term: "الذرية", definition: "الذرية (Atomisme) — المذهب المفسر للكون انطلاقاً من حركة الذرات في الخلاء (عند ديموقريطس وأبيقور)، أو الذرية المنطقية (عند راسل)." },
    { term: "الانتباه", definition: "الانتباه (Attention) — توجيه الوعي وتركيز النشاط الذهني الإرادي أو التلقائي نحو موضوع محدد." },
    { term: "الموقف / الاتجاه", definition: "الموقف (Attitude) — الاستعداد النفسي والعقلي المسبق للتصرف أو الحكم بطريقة معينة إزاء موضوع أو فكرة." },
    { term: "الصفة الجوهرية / المحمول", definition: "الصفة / المحمول (Attribut) — ما يُنسب إلى الجوهر بوصفه مقوماً له (كما عند سبينوزا: الفكر والامتداد)، أو المحمول في القضية المنطقية." },
    { term: "الاكتفاء الذاتي", definition: "الاكتفاء الذاتي (Autarcie) — استقلال الفرد أو الدولة استقلالا تاماً وعدم الحاجة إلى الغير في المعيشة أو الفضيلة." },
    { term: "الأصالة", definition: "الأصالة (Authenticité) — صدق الوجود الإنساني ومطابقته لذاته الحقيقية دون زيف أو انسياق وراء القطيع (مفهوم مركزي عند هيدغر وسارتر)." },
    { term: "الحكم المطلق", definition: "الأوتوقراطية (Autocratie) — نظام حكم يستمد فيه الحاكم سلطته من ذاته دون رقابة شعبية أو دستورية." },
    { term: "العصامية", definition: "العصامية (Autodidaxie) — تكوين الفرد لنفسه معرفياً وفكرياً بجهده الذاتي دون معلم." },
    { term: "الآلة الذاتية / الأوتومات", definition: "الأوتومات (Automate) — الكائن أو الجهاز الذي يتحرك بآلية داخلية محضة دون وعي أو إرادة حرة (نظرية الحيوان-الآلة عند ديكارت)." },
    { term: "الآلية النفسية", definition: "الآلية النفسية (Automatisme) — صدور الأفعال أو الأفكار بصورة لاإرادية وتلقائية دون تدخل الوعي المفكر." },
    { term: "الاستقلال الذاتي", definition: "الاستقلال الذاتي (Autonomie) — قدرة الإرادة العاقلة على أن تشرّع لنفسها قانونها الأخلاقي بنفسها بعيداً عن الأهواء والسلطات الخارجية (أساس الأخلاق الكانطية)." },
    { term: "السلطة", definition: "السلطة (Autorité) — القدرة المشروعة على الإلزام والتوجيه، أو الثقة الممنوحة لمرجع فكري دون برهان مستقل." },
    { term: "السلطوية", definition: "السلطوية (Autoritarisme) — النزعة القائمة على فرض الطاعة المطلقة وقمع حرية الرأي والنقد." },
    { term: "الغير", definition: "الغير (Autrui) — الأنا الآخر؛ الذات البشرية الأخرى التي تشبهني وتختلف عني في آن واحد." },
    { term: "البديهية", definition: "البديهية (Axiome) — قضية أولى واضحة بذاتها لا تحتاج إلى برهان وتُتخذ أساساً لكل بناء استنباطي." },
    { term: "علم القيم / الأكسيولوجيا", definition: "الأكسيولوجيا / علم القيم (Axiologie) — المبحث الفلسفي الذي يدرس طبيعة القيم (الحق، الخير، الجمال) ومعاييرها وتراتبيتها." },
    
    // ==========================================
    // --- حرف B (الدفعة الثانية من الكتاب الأول) ---
    // ==========================================
    { term: "البابية / اللفظية الفارغة", definition: "اللفظية الفارغة (Bavardage / Verbiage) — الكلام المرسل الخالي من المضمون الفكري الدقيق أو البرهان المنطقي." },
    { term: "الباروك", definition: "الباروك (Baroque) — مقولة جمالية وتاريخية تدل على الأسلوب القائم على الحركة والغلو والتعقيد واللاتماثل، وتُستعمل مجازاً لوصف النسق الفكري غير المتوازن." },
    { term: "الهمجية / البربرية", definition: "الهمجية (Barbarie) — حالة اجتماعية وثقافية تتسم بغياب القوانين المدنية والمعايير العقلانية والأخلاقية، في مقابل الحضارة." },
    { term: "القاعدة / الأساس", definition: "القاعدة (Base) — المرتكز النظري أو التجريبي الذي يُبنى عليه نسق علمي أو فلسفي أو بنية اجتماعية." },
    { term: "الغبطة", definition: "الغبطة (Béatitude) — حالة السعادة الروحية القصوى والاكتمال الباطني الدائم الناتج عن المعرفة العقلية العليا أو الاتصال بالمطلق (كما عند سبينوزا)." },
    { term: "الجميل", definition: "الجميل (Beau) — إحدى القيم العليا الثلاث (الحق، الخير، الجميل)؛ وهو ما يبعث في النفس متعة تأملية خالصة منزّهة عن الغرض المنفعي (عند كانط)." },
    { term: "الجمال", definition: "الجمال (Beauté) — الصفة القائمة في الموضوع الفني أو الطبيعي والمولّدة للإحساس بالجميل، وتتجاذبها تفسيرات موضوعية (التناسب والنظام) وذاتية (الذوق)." },
    { term: "السلوكية", definition: "السلوكية (Behaviorisme) — مذهب في علم النفس يرفض منهج الاستبطان الداخلي ويقصر الدراسة العلمية على السلوك الظاهر القابل للملاحظة والقياس (مثير واستجابة)." },
    { term: "الإحسان / فعل الخير", definition: "الإحسان (Bienfaisance) — الميل الإرادي والعملي لفعل الخير للغير وتخفيف آلامهم بدافع الواجب أو التعاطف." },
    { term: "الخير", definition: "الخير (Bien) — المفهوم الأخلاقي المحوري الذي يدل على كل ما هو جدير بالطلب لذاته ويمثل غاية الفعل الأخلاقي، وتختلف مذاهب الفلسفة في تحديد ماهيته." },
    { term: "الخير الأسمى", definition: "الخير الأسمى (Souverain Bien / Summum Bonum) — الغاية المطلقة والنهائية للسلوك الإنساني والتي تتكامل فيها الفضيلة والسعادة التامة (أرسطو وكانط)." },
    { term: "الخير العام", definition: "الخير العام (Bien commun) — المصلحة الكلية المشتركة التي تجمع أفراد المجتمع السياسي وتعلو على المصالح الفردية الضيقة." },
    { term: "الثنائية القطبية", definition: "الثنائية القطبية (Bipolarité) — خاصية المفاهيم والقيم التي تنتظم في أزواج متقابلة ومتلازمة (مثل: الذات والموضوع، الخير والشر)." },
    { term: "علم الأحياء / البيولوجيا", definition: "البيولوجيا (Biologie) — العلم الباحث في قوانين الحياة والكائنات الحية، ويناقش لالاند إشكالاتها المنهجية بين التفسير الآلي والغائي." },
    { term: "النزعة البيولوجية", definition: "النزعة البيولوجية (Biologisme) — الاتجاه الذي يرد الظواهر النفسية والأخلاقية والاجتماعية إلى مجرد آليات وقوانين بيولوجية." },
    { term: "الحس السليم", definition: "الحس السليم (Bon sens) — ملكة الحكم الصائب والتمييز الفطري بين الحق والباطل لدى عامة البشر، وهي أعدل الأشياء قسمة بين الناس عند ديكارت." },
    { term: "السعادة", definition: "السعادة (Bonheur) — حالة الرضا الشامل والدائم عن الوجود، الناتجة عن إشباع ميول الإنسان الجوهرية وتحقيق كماله العقلاني والأخلاقي." },
    { term: "البرجوازية", definition: "البرجوازية (Bourgeoisie) — مفهوم اجتماعي واقتصادي وفلسفي يرتبط بنشأة الرأسمالية وقيم الفردية والملكية الخاصة في الفلسفة الحديثة والماركسية." },
    { term: "الوحشية / الفظاظة", definition: "الوحشية (Brutalité) — خضوع السلوك للاندفاع الغريزي الأعمى أو العنف المادي مع غياب العقل والإرادة الأخلاقية." },

    // ==========================================
    // --- حرف C (الدفعة الثانية من الكتاب الأول) ---
    // ==========================================
    { term: "الكابالا / القبالة", definition: "القبالة (Cabale / Kabbale) — التقليد الصوفي والباطني اليهودي القائم على التأويل الرمزي والعددي للنصوص المقدسة، وقد أثر في بعض فلاسفة عصر النهضة." },
    { term: "الحساب المنطقي", definition: "الحساب (Calcul) — نسق من العمليات الرمزية المضبوطة بقواعد صورية لإنتاج نتائج يقينية (مثل الحساب المنطقي وحساب الاحتمالات)." },
    { term: "حساب اللذات", definition: "حساب اللذات (Calcul des plaisirs) — المنهج النفعـي (عند بنتام) لقياس كمية اللذة والألم المترتبة على الفعل لتحديد قيمته الأخلاقية." },
    { term: "القدرة / الأهلية", definition: "القدرة (Capacité) — الإمكانية الفعلية أو القانونية للقيام بعمل أو استيعاب معرفة أو تحمل مسؤولية." },
    { term: "الحدّ / النهاية", definition: "الحدّ (Borne / Cap) — ما يحصر الشيء في نطاق معين ويفصله عما سواه." },
    { term: "الرأسمالية", definition: "الرأسمالية (Capitalisme) — النظام الاقتصادي والاجتماعي القائم على الملكية الخاصة لوسائل الإنتاج وحرية السوق وتراكم رأس المال." },
    { term: "الطبع / الشخصية", definition: "الطبع (Caractère) — مجموع السمات النفسية والأخلاقية الثابتة نسبياً التي تميز سلوك الفرد وتميزه عن غيره." },
    { term: "الخاصية المميزة", definition: "الخاصية (Caractéristique) — السمة الجوهرية التي تحدد ماهية الشيء أو المفهوم وتميزه منطقياً عما عداه." },
    { term: "السمة الكلية / الكاريكاتير الفكري", definition: "السمة الكلية (Caractéristique universelle) — مشروع ليبنتز لبناء لغة رمزية عالمية وحساب منطقي يحل الخلافات الفلسفية بالبرهان." },
    { term: "الديكارتية", definition: "الديكارتية (Cartésianisme) — المذهب الفلسفي والعلمي المنسوب إلى رينيه ديكارت، والقائم على الشك المنهجي والكوجيتو والثنائية بين الفكر والامتداد." },
    { term: "الحالة / الواقعة الجزئية", definition: "الحالة (Cas) — الواقعة الفردية الخاصة التي تطرح إشكالاً في تطبيق القاعدة العامة (أساس علم الحالات الأخلاقية أو الكازويستيك)." },
    { term: "الفقه الأخلاقي / الكازويستيك", definition: "الكازويستيك (Casuistique) — دراسة الحالات الأخلاقية الفردية المعقدة التي تتعارض فيها الواجبات لتحديد الحكم المناسب لكل حالة." },
    { term: "القطعي / الجازم", definition: "القطعي (Catégorique) — ما يُثبت أو يُؤمر به بصورة مطلقة دون شرط أو قيد (مثل الأمر القطعي الأخلاقي عند كانط)." },
    { term: "المقولة", definition: "المقولة (Catégorie) — المفاهيم الكلية الأساسية والأكثر عمومية التي ينتظم تحتها الوجود (عند أرسطو) أو التي يركب بها الفهم معطيات التجربة (عند كانط)." },
    { term: "التطهر / الكاثارسيس", definition: "التطهر (Catharsis) — تنقية النفس من الانفعالات الضارة عبر الفن التراجيدي (عند أرسطو) أو استعادة الذكريات المكبوتة (في التحليل النفسي)." },
    { term: "السببية / العلية", definition: "السببية / العلية (Causalité) — المبدأ العقلي أو القانون الطبيعي الذي يربط كل ظاهرة (معلول) بظاهرة سابقة أو مصاحبة لها (علة) ارتباطاً ضرورياً." },
    { term: "العلة / السبب", definition: "العلة (Cause) — ما يصدر عنه وجود شيء آخر أو تغيره؛ وقد قسمها أرسطو إلى أربع علل: مادية، صورية، فاعلة، وغائية." },
    { term: "العلة الأولى", definition: "العلة الأولى (Cause première) — المبدأ الأسمى غير المعلول لغيره والذي ينتهي إليه تسلسل العلل في الميتافيزيقيا." },
    { term: "العلة الغائية", definition: "العلة الغائية (Cause finale) — الهدف أو الغرض الذي من أجله يُنجز الفعل أو يوجد الشيء." },
    { term: "المذهب المناسباتي", definition: "المناسباتية (Occasionalisme / Causalisme) — المذهب القائل بأن الحوادث المادية ليست عللاً حقيقية بل مجرد مناسبات يتدخل فيها الله لإحداث الأثر (مالبرانش)." },
    { term: "الخلية", definition: "الخلية (Cellule) — الوحدة البنيوية والوظيفية الأساسية للكائن الحي في البيولوجيا الحديثة." },
    { term: "الرقابة / الكبت", definition: "الرقابة (Censure) — السلطة الخارجية التي تمنع نشر الأفكار، أو الآلية النفسية اللاواعية التي تمنع الرغبات المكبوتة من الصعود إلى الوعي (فرويد)." },
    { term: "المركزية", definition: "المركزية (Centralisation) — تجميع السلطة أو الوظائف التنظيمية في نقطة واحدة حاكمة." },
    { term: "المركز", definition: "المركز (Centre) — نقطة الارتكاز التي تدور حولها العناصر أو تستمد منها توازنها." },
    { term: "اليقين", definition: "اليقين (Certitude) — الحالة الذهنية المتمثلة في الاقتناع التام والراسخ بحقيقة قضية ما مع انتفاء كل شك أو احتمال للخطأ." },
    { term: "السلسلة / التسلسل", definition: "التسلسل (Chaîne) — تتابع الحلقات أو القضايا المنطقية والعلية بحيث يرتبط كل عنصر بسابقه ولاحقه." },
    { term: "الصدفة / البخت", definition: "الصدفة (Chance / Hasard) — التقاء سلسلتي علل مستقلتين ينجم عنه حدث غير متوقع، أو درجة احتمال تحقق حدث ما." },
    { term: "التغير", definition: "التغير (Changement) — كل انتقال للشيء من حالة إلى أخرى في الكيف أو الكم أو المكان أو الجوهر (الصيرورة)." },
    { term: "الفوضى الكونية / الكاوس", definition: "الكاوس / العماء (Chaos) — حالة الاضطراب الأولي وانعدام النظام قبل تشكل الكون المنظم (الكوسموس)." },
    { term: "المسيحية الفلسفية", definition: "المسيحية (Christianisme) — المنظومة الدينية والفلسفية التي أثرت في مفاهيم الخلق والحرية والشخص والتاريخ في الفكر الغربي." },
    { term: "الشيء", definition: "الشيء (Chose) — كل موجود مستقل له قوام واقعي، في مقابل الفكر أو الشخص العاقل (ويُميز كانط بين الظاهرة والشيء في ذاته)." },
    { term: "الشيئية", definition: "الشيئية (Chosisme) — النزعة المنهجية الداعية إلى دراسة الظواهر الإنسانية والاجتماعية بوصفها أشياء خارجية مستقلة (كما عند دوركايم)." },
    { term: "الزمني / الكرونولوجي", definition: "الكرونولوجي (Chronologique) — ما يرتبط بترتيب الأحداث وفق تعاقبها في الزمان التاريخي." },
    { term: "الدور المنطقي", definition: "الدور / المصادرة على المطلوب (Cercle vicieux) — خطأ منطقي يقوم على إثبات قضية بمقدمة تتوقف صحتها أصلاً على تلك القضية ذاتها." },
    { term: "الدائرة الهيرمينوطيقية", definition: "الدائرة التأويلية (Cercle herméneutique) — التفاعل المتبادل بين فهم الجزء وفهم الكل في عملية تفسير النصوص." },
    { term: "المدنية / الحضارة", definition: "الحضارة (Civilisation) — مجموع المكتسبات العقلية والمادية والأخلاقية والاجتماعية التي ترقى بالإنسان وتخرجه من حالة الطبيعة." },
    { term: "المدني", definition: "المدني (Civil) — ما يتعلق بالمواطن وبحالة الاجتماع المنظم بالقوانين في مقابل الحالة الطبيعية أو الدينية أو العسكرية." },
    { term: "الوضوح", definition: "الوضوح (Clarté) — صفة الفكرة الحاضرة والجليّة للذهن المنتبه بحيث لا يلتبس إدراكها (معيار الحقيقة عند ديكارت)." },
    { term: "الطبقة / الصنف", definition: "الصنف / الطبقة (Classe) — مجموعة من الكائنات أو العناصر تشترك في خاصية أو أكثر وتندرج تحت مفهوم واحد في المنطق أو علم الاجتماع." },
    { term: "التصنيف", definition: "التصنيف (Classification) — توزيع الموضوعات أو العلوم أو الكائنات في فئات متدرجة ومنظمة وفق مبادئ منطقية أو طبيعية." },
    { term: "الكلاسيكي", definition: "الكلاسيكي (Classique) — ما يُعد نموذجاً معيارياً متوازناً يجمع بين صفاء العقل وجمال الشكل، في مقابل الرومانسي أو الباروكي." },
    { term: "الشمول / الانغلاق", definition: "الانغلاق (Clôture) — اكتمال النسق الفكري أو المنطقي واكتفاؤه بمبادئه الداخلية دون الحاجة إلى عناصر خارجية." },
    { term: "الالتزام المشترك / التعايش", definition: "التعايش (Coexistence) — وجود أشياء أو مبادئ متعددة معاً في آن واحد دون أن ينفي بعضها بعضاً." },
    { term: "الكوجيتو", definition: "الكوجيتو (Cogito) — مبدأ ديكارت التأسيسي (أنا أفكر، إذن أنا موجود) بوصفه الحقيقة اليقينية الأولى التي تقاوم الشك المنهجي." },
    { term: "المعرفة / الإدراك العقلي", definition: "المعرفة الذهنية (Cognition) — مجموع العمليات العقلية التي يتم بواسطتها اكتساب المعارف وتنظيمها واستخدامها." },
    { term: "التماسك / الاتساق", definition: "الاتساق (Cohérence) — الترابط المنطقي الداخلي بين قضايا النسق الواحد وخلوه من التناقض." },
    { term: "التطابق / التزامن", definition: "التصادف / التطابق (Coïncidence) — اتفاق حدثين في الزمان أو المكان أو تطابق مفهومين في الماصدق." },
    { term: "الجماعي", definition: "الجماعي (Collectif) — ما يخص الجماعة ككل ويمتلك خصائص تتجاوز مجرد مجموع الأفراد المكونين لها (مثل الوعي الجمعي عند دوركايم)." },
    { term: "الجماعية", definition: "الجماعية (Collectivisme) — المذهب الاجتماعي والاقتصادي القائل بالملكية الجماعية لوسائل الإنتاج وتغليب مصلحة الجماعة." },
    { term: "التأليف / التركيب التوافقي", definition: "التأليف (Combinaison) — جمع عناصر مختلفة لإنتاج مركب جديد ذي خصائص نوعية متميزة (فن التأليف عند ليبنتز)." },
    { term: "المشترك / الحس المشترك", definition: "الحس المشترك (Sens commun) — المعتقدات البديهية السائدة لدى عامة الناس، أو الملكة التي توحد معطيات الحواس الخمس (عند أرسطو)." },
    { term: "التواصل", definition: "التواصل (Communication) — تبادل الأفكار والمشاعر والدلالات بين الذوات الواعية عبر اللغة أو الرموز." },
    { term: "المجتمع المحلي / الجماعة", definition: "الجماعة (Communauté) — رابطة إنسانية عضوية تقوم على الاشتراك في القيم والتاريخ والمصير، في مقابل المجتمع التعاقدي." },
    { term: "الشيوعية", definition: "الشيوعية (Communisme) — المذهب السياسي والاجتماعي الداعي إلى إلغاء الملكية الخاصة والطبقات الاجتماعية وإقامة مجتمع المساواة التامة." },
    { term: "المقارنة", definition: "المقارنة (Comparaison) — العملية الذهنية التي تقابل بين شيئين أو أكثر لاستخراج أوجه التشابه والاختلاف بينهما." },
    { term: "التوافق / إمكان الاجتماع", definition: "التوافق (Compatibilité) — قابلية قضيتين أو صفتين للاجتماع معاً دون تناقض منطقي أو واقعي." },
    { term: "التعويض", definition: "التعويض (Compensation) — استعادة التوازن النفسي أو الأخلاقي أو الكوني عبر مقابلة النقص أو الضرر بما يعادله." },
    { term: "التكامل", definition: "التكامل (Complémentarité) — علاقة بين مظهرين أو تفسيرين يبدوان متعارضين لكنهما ضروريان معاً لإدراك الحقيقة الكاملة (كما في فيزياء الكم عند بور)." },
    { term: "المركّب / المعقّد", definition: "المركّب (Complexe) — ما يتألف من عناصر متعددة متشابكة يصعب فصلها، أو العقدة النفسية المكبوتة في اللاوعي (يونغ وفرويد)." },
    { term: "السلوك", definition: "السلوك (Comportement) — مجموع استجابات الكائن الحي وأفعاله الملاحظة تجاه مثيرات الوسط الخارجي والداخلي." },
    { term: "الفهم / الاستيعاب", definition: "الفهم (Compréhension) — إدراك المعنى الباطني والدلالة والغائية للظواهر الإنسانية (في مقابل التفسير العلي)، وفي المنطق: مجموع الصفات المكونة للمفهوم." },
    { term: "التسوية / الحل الوسط", definition: "التسوية (Compromis) — اتفاق عملي يتنازل فيه كل طرف عن جزء من مطالبه لتفادي الصراع، وهو مرفوض في مجال المبادئ المنطقية." },
    { term: "العدّ / الإحصاء", definition: "العدّ (Compte) — تحديد الكمية المنفصلة عبر تعيين الوحدات العددية المتتالية." },
    { term: "المفهوم / التصور", definition: "المفهوم (Concept) — الفكرة العامة والمجردة التي يبنيها العقل لتوحيد الكثرة الحسية تحت دلالة واحدة ثابتة." },
    { term: "التصورية / المفهومية", definition: "المفهومية (Conceptualisme) — المذهب القائل بأن الكليات (الأجناس والأنواع) لا توجد في الخارج كأعيان مستقلة ولا هي مجرد أسماء، بل هي مفاهيم في الذهن." },
    { term: "التصور / الحمل", definition: "التصور (Conception) — فعل الذهن في تكوين المفهوم وإدراكه، أو الرؤية الشاملة للعالم (نظرة كونية)." },
    { term: "الملموس / العيني", definition: "العيني / الملموس (Concret) — الواقع الفردي المتعين بجميع خصائصه الحسية والوجودية، في مقابل المجرد (Abstrait)." },
    { term: "النتيجة المنطقية", definition: "النتيجة (Conclusion) — القضية التي تلزم بالضرورة عن المقدمات في الاستدلال والقياس المنطقي." },
    { term: "التزامن / التلاقي", definition: "التلاقي (Concomitance) — وقوع ظاهرتين معاً بانتظام دون أن تكون إحداهما بالضرورة علة للأخرى." },
    { term: "الوفاق / التناغم", definition: "التناغم (Concorde) — الانسجام بين الإرادات والعقول داخل المجتمع أو بين قوى النفس." },
    { term: "التزاحم / المنافسة", definition: "المنافسة (Concurrence) — التنازع بين قوى أو أفراد لبلوغ غاية واحدة أو البقاء في الوسط الطبيعي والاجتماعي." },
    { term: "الإدانة / الاستهجان", definition: "الإدانة (Condamnation) — الحكم الأخلاقي أو القانوني القاطع برفض فعل ما بوصفه شراً أو جريمة." },
    { term: "الشرط", definition: "الشرط (Condition) — ما يتوقف عليه وجود الشيء أو تحقق الحدث أو صحة القضية (شرط ضروري وشرط كافٍ)." },
    { term: "الشرطية", definition: "الشرطية (Conditionnalité) — خضوع الظواهر أو الأحكام لشروط محددة تقيد إطلاقها." },
    { term: "الإشراط", definition: "الإشراط (Conditionnement) — ربط استجابة انعكاسية بمثير جديد عبر الاقتران المتكرر (عند بافلوف)، أو تأثير الوسط في الفرد." },
    { term: "السلوك الموجه / التصرف", definition: "التصرف (Conduite) — السلوك الإنساني الهادف والمشحون بالدلالة النفسية والاجتماعية (عند بيير جانيه)." },
    { term: "الاعتراف / الإقرار", definition: "الإقرار (Confession / Aveu) — شهادة الذات على أفعالها أو أفكارها الباطنة أمام نفسها أو أمام الغير." },
    { term: "الثقة", definition: "الثقة (Confiance) — الاطمئنان الأخلاقي والمعرفي إلى صدق الغير أو نجاعة العقل." },
    { term: "التكوين / البنية الشكلية", definition: "البنية الشكلية (Configuration) — الترتيب المكاني أو البنيوي للعناصر الذي يمنح الكل صورته المميزة (نظرية الجشطلت)." },
    { term: "الصراع", definition: "الصراع (Conflit) — التصادم بين قوى أو رغبات أو قيم متعارضة داخل النفس أو في التاريخ والمجتمع." },
    { term: "المطابقة / الامتثال", definition: "الامتثال (Conformité) — توافق الفعل أو الفكر مع قاعدة أو نموذج أو عرف سائد." },
    { term: "الامتثالية", definition: "الامتثالية (Conformisme) — الخضوع السلبي للأعراف والآراء السائدة في المجتمع دون تفكير نقدي مستقل." },
    { term: "الخلط / الغموض", definition: "الخلط (Confusion) — عدم التمييز بين عناصر الفكرة الواحدة أو بين فكرتين مختلفتين (نقيض التمايز عند ديكارت)." },
    { term: "التخمين / الحدس الظني", definition: "التخمين (Conjecture) — فرضية أو رأي محتمل يقوم على أمارات غير يقينية في انتظار البرهان." },
    { term: "الاقتران / الوصل", definition: "الوصل المنطقي (Conjonction) — الربط بين قضيتين بأداة العطف (و)، وتكون القضية المركبة صادقة فقط إذا صدق طرفاها معاً." },
    { term: "المعرفة", definition: "المعرفة (Connaissance) — الفعل العقلي الذي تدرك به الذات موضوعاً ما، أو حصيلة هذا الإدراك من حقائق ومفاهيم." },
    { term: "نظرية المعرفة", definition: "نظرية المعرفة (Théorie de la connaissance / Gnoséologie) — المبحث الفلسفي الذي يدرس طبيعة المعرفة ومصادرها وقيمتها وحدودها." },
    { term: "الطبيعة المشتركة / التجانس الجوهري", definition: "التجانس الجوهري (Connaturalité) — المعرفة التي تتم عبر التآلف الباطني والمشاركة الوجدانية مع الموضوع." },
    { term: "الارتباط / التلاحم", definition: "التلاحم (Connexion) — الرابطة الوثيقة التي تجعل عنصرين متلازمين منطقياً أو واقعياً." },
    { term: "التضمين / الدلالة الحافة", definition: "التضمين (Connotation) — مجموع الصفات والخصائص التي يتضمنها المفهوم (مفهوم اللفظ)، في مقابل ما يصدق عليه من أفراد (الماصدق)." },
    { term: "الوعي", definition: "الوعي (Conscience) — الحدس المباشر الذي تدرك به الذات ذاتها وأحوالها وأفعالها والعالم المحيط بها (وعي سيكولوجي ووعي أخلاقي)." },
    { term: "الضمير الأخلاقي", definition: "الضمير الأخلاقي (Conscience morale) — الملكة الباطنية التي تصدر أحكام القيمة على الأفعال من حيث الخير والشر وتلزم بالواجب." },
    { term: "التكريس / القداسة", definition: "التكريس (Consécration) — إضفاء طابع القداسة أو الاعتراف الرسمي والقيمي على فكرة أو مؤسسة." },
    { term: "الإجماع", definition: "الإجماع (Consensus) — اتفاق العقول أو أفراد المجتمع على مبدأ أو حقيقة بوصفها أساساً للتعايش أو اليقين." },
    { term: "النتيجة / اللازم", definition: "اللازم / النتيجة (Conséquence) — ما يترتب بالضرورة المنطقية على مبدأ أو مقدمة، أو الأثر العملي الناتج عن فعل." },
    { term: "النتائجية / العواقبية", definition: "العواقبية (Conséquentialisme) — المذهب الأخلاقي الذي يقيس صواب الفعل أو خطأه بناءً على نتائجه وعواقبه فقط." },
    { term: "المحافظة", definition: "المحافظة (Conservatisme) — الاتجاه الفكري والسياسي الداعي إلى صون التقاليد والمؤسسات القائمة ومقاومة التغيير الجذري." },
    { term: "البقاء / الحفظ", definition: "الحفظ (Conservation) — استمرار الشيء في الوجود وبقاء كمية المادة أو الطاقة ثابتة رغم التحولات (مبدأ انحفاظ الطاقة)." },
    { term: "التأمل العميق / الاعتبار", definition: "الاعتبار (Considération) — فحص الموضوع برويّة وتقدير قيمته وأبعاده المختلفة." },
    { term: "الاتساق / الثبات", definition: "الثبات (Consistance) — خلو النسق المنطقي من التناقض، أو صلابة الشخصية واستقرار مبادئها." },
    { term: "العزاء الفلسفي", definition: "العزاء (Consolation) — التماس الطمأنينة والسكينة في العقل والحكمة لمواجهة آلام الوجود والموت (كما عند بوثيوس والرواقيين)." },
    { term: "الثبات / الاطراد", definition: "الاطراد (Constance) — عدم تغير العلاقة أو القانون عبر الزمان والمكان رغم تعدد الحالات." },
    { term: "المعاينة / الإثبات التجريبي", definition: "المعاينة (Constatation) — تسجيل الواقعة كما تبدو في التجربة المباشرة دون تأويل نظري مسبق." },
    { term: "المكوّن / التأسيسي", definition: "التأسيسي (Constitutif) — ما يدخل في صميم بناء الشيء أو المعرفة ويمنحه ماهيته (في مقابل التنظيمي عند كانط)." },
    { term: "البناء / التشييد", definition: "البناء (Construction) — تركيب المفاهيم أو البراهين أو الأنساق الفلسفية عبر نشاط العقل التركيبي." },
    { term: "البنائية", definition: "البنائية (Constructivisme) — المذهب القائل بأن المعرفة والواقع الاجتماعي والرياضي ليست معطيات جاهزة بل هي بناءات يشيدها العقل والنشاط الإنساني." },
    { term: "التأمل النظري", definition: "التأمل (Contemplation) — النشاط العقلي الخالص الموجه لإدراك الحقيقة أو الجمال لذاتهما دون غرض عملي نفعـي (الحياة التأملية عند أرسطو)." },
    { term: "المعاصرة", definition: "المعاصرة (Contemporanéité) — الاشتراك في الفترة الزمنية الواحدة أو الانتماء إلى روح العصر الحاضر." },
    { term: "المضمون / المحتوى", definition: "المضمون (Contenu) — المادة الفكرية أو الحسية التي تملأ الصورة المنطقية أو الشكل الفني (مقابل الشكل Forme)." },
    { term: "السياق", definition: "السياق (Contexte) — الإطار اللغوي أو التاريخي أو الفكري الذي يحيط بالنص أو الحدث ويحدد دلالته الدقيقة." },
    { term: "التجاور الزمني والمكاني", definition: "التجاور (Contiguïté) — التلاصق في المكان أو التعاقب المباشر في الزمان، وهو أحد قوانين تداعي الأفكار عند هيوم." },
    { term: "الإمكان / الجواز", definition: "الإمكان / العرضية (Contingence) — صفة ما يمكن أن يوجد أو لا يوجد، وما يقع دون ضرورة منطقية أو حتمية مطلقة (مقابل الضرورة)." },
    { term: "الاستمرارية / الاتصال", definition: "الاتصال (Continuité) — غياب الانقطاع أو الفجوات في الزمان أو المكان أو التطور (مبدأ لايبنتز: الطبيعة لا تقفز)." },
    { term: "المتصل", definition: "المتصل (Continu) — الكم أو الامتداد القابل للقسمة إلى ما لا نهاية دون أن يتألف من نقاط منفصلة." },
    { term: "العقد", definition: "العقد (Contrat) — اتفاق حر بين إرادتين أو أكثر ينشئ التزامات متبادلة (نظرية العقد الاجتماعي عند هوبز ولوك وروسو)." },
    { term: "التناقض", definition: "التناقض (Contradiction) — الجمع بين إثبات الشيء ونفيه في آن واحد ومن جهة واحدة، وهو ما يرفضه العقل وفق مبدأ عدم التناقض." },
    { term: "التضاد", definition: "التضاد (Contrariété) — التقابل بين حدين يقعان في أقصى طرفي الجنس الواحد (مثل الأبيض والأسود)، بحيث لا يجتمعان ولكن قد يرتفعان معاً." },
    { term: "المراقبة / التحقق", definition: "التحقق (Contrôle) — فحص صحة الفرضيات أو سلامة العمليات العقلية ومطابقتها للمعايير." },
    { term: "الجدل / السجال", definition: "السجال (Controverse) — النقاش الفكري المطول حول مسألة خلافية تتباين فيها وجهات النظر." },
    { term: "المواضعة / الاتفاق", definition: "المواضعة (Convention) — قاعدة أو رمز أو نظام يتم إقراره باتفاق ضمني أو صريح بين البشر دون أن تفرضه الطبيعة بالضرورة." },
    { term: "المواضعاتية", definition: "المواضعاتية (Conventionnalisme) — المذهب الإبستمولوجي (عند بوانكاريه) القائل بأن مسلمات الهندسة ومبادئ الفيزياء هي مواضعات عقلية ملائمة وليست حقائق مطلقة." },
    { term: "التقارب", definition: "التقارب (Convergence) — اتجاه مسارات فكرية أو علمية مستقلة نحو نتيجة أو نقطة التقاء واحدة." },
    { term: "العكس المنطقي / التحول", definition: "العكس المنطقي (Conversion) — قلب حدي القضية (جعل الموضوع محمولاً والمحمول موضوعاً) مع الحفاظ على صدقها، أو التحول الروحي الجذري." },
    { term: "الاقتناع", definition: "الاقتناع (Conviction) — التسليم العقلي بصحة رأي أو مبدأ بناءً على أدلة يراها الفرد كافية وذاتية." },
    { term: "التعاون", definition: "التعاون (Coopération) — العمل المشترك والمنظم بين الأفراد لبلوغ غاية واحدة تتجاوز قدرات الفرد المنعزل." },
    { term: "التنسيق", definition: "التنسيق (Coordination) — تنظيم العناصر أو الأفعال المتكافئة في نسق متناغم دون تبعية أحدهما للآخر." },
    { term: "النسخة / المحاكاة", definition: "النسخة (Copie) — إعادة إنتاج نموذج أصلي؛ وتُناقش في نظرية المعرفة حول مدى كون الفكرة مجرد نسخة من الانطباع الحسي (هيوم)." },
    { term: "الجسم / الجسد", definition: "الجسم / الجسد (Corps) — الامتداد المادي القابل للإدراك الحسي، أو الكيان العضوي الحي المرتبط بالنفس والوعي." },
    { term: "النتيجة الفرعية / اللازمة", definition: "النتيجة الفرعية (Corollaire) — قضية تستنتج مباشرة وبسهولة من قضية سابقة سبق البرهان عليها." },
    { term: "التلازم / الارتباط المتبادل", definition: "التلازم (Corrélation) — العلاقة المتبادلة بين حدين أو متغيرين بحيث يستدعي وجود أحدهما وجود الآخر أو يتغير بتغيره." },
    { term: "التطابق / المراسلة", definition: "التطابق (Correspondance) — التناظر الدقيق بين عناصر مجموعتين أو بين الفكر والواقع الخارجي." },
    { term: "الفساد / الانحلال", definition: "الفساد (Corruption) — تفكك المركب وزوال صورته الجوهرية (يقابل الكون والنشوء عند أرسطو)، أو الانحراف الأخلاقي." },
    { term: "الكونيات / الكوسمولوجيا", definition: "الكوسمولوجيا (Cosmologie) — المبحث الفلسفي والعلمي الباحث في أصل الكون وبنيته وقوانينه الكلية بوصفه كلاً منظماً." },
    { term: "العالمية / الكوسموبوليتية", definition: "الكوسموبوليتية (Cosmopolitisme) — النزعة الفلسفية والأخلاقية القائلة بأن البشر جميعاً مواطنون في عالم واحد وتجمعهم إنسانية مشتركة فوق الحدود القومية." },
    { term: "الكون المنظم / الكوسموس", definition: "الكوسموس (Cosmos) — العالم منظوراً إليه كنظام جميل ومتناغم محكوم بقوانين عقلية، في مقابل الفوضى." },
    { term: "الشجاعة", definition: "الشجاعة (Courage) — إحدى الفضائل الأساسية الأربع عند أفلاطون؛ وهي ثبات النفس وإقدامها العقلاني في مواجهة الخطر والألم دفاعاً عن الحق." },
    { term: "العرف / العادة الاجتماعية", definition: "العرف (Coutume) — القواعد السلوكية غير المكتوبة التي استقرت بالتكرار التاريخي واكتسبت قوة إلزامية في المجتمع." },
    { term: "الاعتقاد", definition: "الاعتقاد (Croyance) — تصديق الذهن بقضية ما والاطمئنان إليها رغم عدم توفر البرهان العلمي أو المنطقي القاطع عليها." },
    { term: "الخلق / الإبداع", definition: "الخلق / الإبداع (Création) — إيجاد شيء جديد من العدم (في اللاهوت والميتافيزيقيا) أو ابتكار صور وقيم أصيلة لم تكن موجودة (في الفن والفلسفة)." },
    { term: "المبدع / الخالق", definition: "المبدع (Créateur) — الفاعل القادر على الإيجاد الأصيل، أو صفة التطور الحيوي المتجدد باستمرار (التطور الخالق عند برغسون)." },
    { term: "الجريمة", definition: "الجريمة (Crime) — الفعل الذي ينتهك القوانين الأساسية للمجتمع والقيم الأخلاقية العليا ويستوجب العقاب." },
    { term: "الأزمة", definition: "الأزمة (Crise) — لحظة التحول الحاسمة والاضطراب العميق في مسار الفرد أو المجتمع أو أسس العلم، والتي تفرض مراجعة شاملة." },
    { term: "المعيار / المحك", definition: "المعيار (Critère) — العلامة المميزة أو القاعدة اليقينية التي يُحتكم إليها للتمييز بين الصدق والكذب أو الخير والشر." },
    { term: "النقد", definition: "النقد (Critique) — الفحص العقلاني للمبادئ والأفكار والأعمال لتحديد قيمتها وحدود مشروعيتها (الفلسفة النقدية عند كانط)." },
    { term: "النقدية", definition: "النقدية (Criticisme) — المذهب الفلسفي الكانطي الذي يجعل من نقد ملكة العقل ذاتها وتحديد حدود المعرفة الممكنة شرطاً سابقاً على كل ميتافيزيقيا." },
    { term: "الثقافة", definition: "الثقافة (Culture) — تنمية ملكات الإنسان العقلية والأخلاقية والجمالية، ومجموع القيم والرموز والإبداعات التي تميز حضارة معينة." },
    { term: "الفضول المعرفي", definition: "الفضول (Curiosité) — الرغبة الفطرية أو العقلية في المعرفة والاستكشاف وكشف المجهول." },
    { term: "الدورة / التعاقب الدوري", definition: "الدورة (Cycle) — سلسلة من الظواهر أو الأحداث التاريخية والطبيعية التي تتكرر بانتظام وتعود إلى نقطة بدايتها (العود الأبدي)." },
    { term: "الكلبية", definition: "الكلبية (Cynisme) — المدرسة الفلسفية السقراطية (أنتيستينس وديوجين) التي دعت إلى العودة للطبيعة والزهد التام واحتقار الأعراف والتقاليد الاجتماعية الزائفة." },
    
    // ==========================================
    // --- حرف D (الدفعة الثالثة من الكتاب الأول) ---
    // ==========================================
    { term: "الدهر / الفلك", definition: "الدهر (Déisme / Durée cosmique / Demiurge) — في اللاهوت والفلسفة: تصور الإله بوصفه خالقاً صانعاً للنظام الكوني دون تدخل دائم في مجرى الأحداث الطبيعية (الدهرية)." },
    { term: "الاستنتاج / الاستنباط", definition: "الاستنباط (Déduction) — استدلال منطقي يتم فيه الانتقال من مقدمات عامة أو مبادئ أولى إلى نتيجة خاصة تلزم عنها بالضرورة." },
    { term: "الاستدلال الاستنباطي", definition: "الاستدلال الاستنباطي (Raisonnement déductif) — نمط من البرهان لا تتجاوز فيه النتيجة ما هو مضمر في المقدمات، وهو أساس الرياضيات والمنطق الصوري." },
    { term: "التعريف / الحد", definition: "التعريف (Définition) — تحديد ماهية الشيء أو المعنى الدقيق للفظ عبر بيان جنسه القريب وفصله النوعي، أو حصر خصائصه المميزة." },
    { term: "التعريف الإجرائي", definition: "التعريف الإجرائي (Définition opérationnelle) — تحديد المفهوم العلمي من خلال العمليات أو الإجراءات التجريبية والقياسية التي تسمح بملاحظته والتحقق منه." },
    { term: "التدهور / الانحطاط", definition: "الانحطاط (Décadence) — مسار التراجع والانهيار الذي يصيب الحضارات أو القيم أو الأنساق الفكرية بعد بلوغ ذروتها." },
    { term: "القرار / العزم", definition: "القرار (Décision) — حسم التردد بين الإمكانات المختلفة عبر فعل إرادي وواعٍ يلتزم بتبعاته." },
    { term: "الاستكشاف / الكشف", definition: "الكشف (Découverte) — إماطة اللثام عن حقيقة أو ظاهرة أو قانون كان قائماً في الواقع ولكن لم يكن معروفاً من قبل." },
    { term: "الإذلال / الحط من الكرامة", definition: "الحط من الكرامة (Dégradation) — إهدار القيمة الذاتية أو الأخلاقية للفرد أو انحدار كائن إلى مستوى أدنى من كماله." },
    { term: "اللامركزية", definition: "اللامركزية (Décentralisation) — توزيع السلطات والاختصاصات الإدارية أو السياسية أو التنظيمية بعيداً عن مركز واحد مطلق." },
    { term: "الديماغوجية", definition: "الديماغوجية (Démagogie) — استمالة الجماهير وتضليلها عبر إثارة العواطف والوعود الزائفة بدل مخاطبة العقل والمنطق." },
    { term: "الديمقراطية", definition: "الديمقراطية (Démocratie) — نظام حكم يقوم على سيادة الشعب ومشاركته المباشرة أو التمثيلية في صناعة القوانين واتخاذ القرارات." },
    { term: "البرهان", definition: "البرهان (Démonstration) — سلسلة من الاستدلالات المنطقية الملزمة التي تنطلق من مبادئ صادقة لتثبيت صدق نتيجة ما بيقين." },
    { term: "اللاأخلاقية / الفساد الخلقي", definition: "الفساد الخلقي (Démoralisation) — تفكك الضوابط الأخلاقية والروحية وفقدان الثقة بالقيم المشتركة." },
    { term: "المذهب الدهري", definition: "الدهرية (Déisme) — الموقف الفلسفي الذي يقر بوجود إله خالق للكون ومصمم لنظامه العقلي، مع إنكار الوحي والنبوات والمعجزات والتدخل المباشر." },
    { term: "التجريد من الصفة القدسية", definition: "نزع القداسة (Désacralisation) — إخراج الظواهر أو المؤسسات أو المفاهيم من دائرة التقديس الديني أو الأسطوري وإخضاعها للعقل أو التاريخ." },
    { term: "الخيبة / فقدان الأوهام", definition: "فقدان الأوهام (Désillusion) — انكشاف زيف التصورات المثالية أو الأوهام الذاتية أمام صدمة الواقع." },
    { term: "الرغبة", definition: "الرغبة (Désir) — ميل نفسي أو حيوي موجه نحو موضوع أو حالة يُتوقع منها إشباع نقص أو جلب لذة أو تحقيق كمال." },
    { term: "الاستبداد", definition: "الاستبداد (Despotisme) — ممارسة السلطة المطلقة والتعسفية دون التقيد بقانون أو إرادة المحكومين (كما حلله مونتسكيو)." },
    { term: "المصير / القدر", definition: "المصير (Destin) — المجرى المحتوم للأحداث أو الغاية النهائية التي يؤول إليها الكائن أو التاريخ." },
    { term: "التدمير / الهدم", definition: "الهدم (Destruction) — إزالة بنية أو كيان أو نسق، وقد يرتبط في الفلسفة المعاصرة بالتفكيك أو نزعة الموت (ثاناتوس)." },
    { term: "التفصيل / الجزئية", definition: "التفصيل (Détail) — العنصر الجزئي الدقيق داخل الكل المركب." },
    { term: "الحتمية", definition: "الحتمية (Déterminisme) — المبدأ القائل بأن كل ظاهرة أو حدث محكوم سلفاً بشروط وعلل ضرورية بحيث لا يمكن أن يقع على نحو آخر في الظروف ذاتها." },
    { term: "الحتمية النفسية", definition: "الحتمية النفسية (Déterminisme psychologique) — القول بأن الأفعال والاختيارات الإنسانية تخضع لعلل ودوافع نفسية ولاواعية حتمية." },
    { term: "التحديد / التعيين", definition: "التعيين (Détermination) — إضفاء صفات أو حدود محددة على ما كان عاماً أو غير متعين، أو إثبات علاقة العلة بالمعلول." },
    { term: "الواجب", definition: "الواجب (Devoir) — الالتزام الأخلاقي الذي يفرضه العقل أو الضمير بوصفه أمراً ملزماً بذاته بغض النظر عن الميول أو النتائج (عند كانط)." },
    { term: "الديالكتيك / الجدل", definition: "الديالكتيك (Dialectique) — فن الحوار والمناظرة لبلوغ الحقيقة (عند سقراط وأفلاطون)، أو منطق الصيرورة وحركة التناقضات (الأطروحة، النقيض، التركيب عند هيغل وماركس)." },
    { term: "الديالكتيك المتعالي", definition: "الديالكتيك المتعالي (Dialectique transcendantale) — القسم من نقد العقل الخالص عند كانط الذي يكشف تناقضات العقل حين يحاول تجاوز حدود التجربة الممكنة." },
    { term: "الخطاب", definition: "الخطاب (Discours) — تسلسل منظم من الأفكار والألفاظ والحجج يعبر عن موقف أو نسق معرفي أو يمارس تأثيراً رمزياً واجتماعياً." },
    { term: "التمييز", definition: "التمييز (Distinction) — الفصل الواضح بين مفهومين أو شيئين مختلفين لتجنب الخلط والالتباس في الفكر." },
    { term: "التمايز", definition: "التمايز (Distinct) — صفة الفكرة الواضحة والمحددة بدقة بحيث لا تختلط بغيرها (معيار الحقيقة عند ديكارت)." },
    { term: "التنوع / الاختلاف", definition: "التنوع (Diversité) — تعدد الصور والخصائص والمظاهر في الواقع أو في التجربة الحسية." },
    { term: "الفقر / الحرمان", definition: "الحرمان (Dénuement / Privation) — غياب صفة أو مقوم كان من شأنه أن يوجد في الشيء أو الذات." },
    { term: "العقيدة الجازمة / الدوغما", definition: "الدوغما (Dogme) — قضية تأسيسية تُقبل كحقيقة راسخة داخل مذهب ديني أو فلسفي دون إخضاعها للشك الدائم." },
    { term: "الدوغمائية", definition: "الدوغمائية (Dogmatisme) — الاتجاه الفلسفي الذي يثق بقدرة العقل على إدراك الحقائق المطلقة دون فحص نقدي مسبق لحدود المعرفة." },
    { term: "الشك", definition: "الشك (Doute) — توقف الذهن أو تردده بين الإثبات والنفي؛ وقد يكون شكاً مطلقاً (عند الشكاك) أو شكاً منهجياً مؤقتاً لبلوغ اليقين (عند ديكارت)." },
    { term: "الحق", definition: "الحق (Droit) — القدرة أو الاستحقاق المشروع الذي تحميه القواعد القانونية أو المبادئ الأخلاقية، أو مجموع القوانين المنظمة للعلاقات." },
    { term: "الحق الطبيعي", definition: "الحق الطبيعي (Droit naturel) — الحقوق الأصيلة الثابتة للإنسان بحكم طبيعته وعقله، السابقة على القوانين الوضعية والمستقلة عنها." },
    { term: "الحق الوضعي", definition: "الحق الوضعي (Droit positif) — القوانين والتشريعات الفعلية التي تضعها السلطة السياسية في مجتمع وزمان محددين." },
    { term: "الديناميكية", definition: "الديناميكية (Dynamisme) — المذهب أو الرؤية التي تجعل من القوة والحركة والفعالية مبدأً أساسياً للوجود والطبيعة في مقابل السكون أو الآلية الجامدة." },
    { term: "الديمومة / المدة", definition: "الديمومة (Durée) — الزمان النفسي المتصل والكيفي الذي تعيشه الوعي مباشرة وتندمج فيه الذكريات بالحاضر، في مقابل الزمن المكاني المقاس (عند برغسون)." },

    // ==========================================
    // --- حرف E (الدفعة الثالثة من الكتاب الأول) ---
    // ==========================================
    { term: "التجربة التربوية / التعليم", definition: "التعليم (Éducation) — الفعل المنظم والمقصود الذي يمارسه الراشدون لتنمية الملكات الجسدية والعقلية والأخلاقية لدى الناشئة ودمجهم في الثقافة." },
    { term: "الفعالية", definition: "الفعالية (Efficacité) — قدرة العلة أو الفعل أو القاعدة على إنتاج الأثر المطلوب أو تحقيق الغاية المنشودة." },
    { term: "العلة الفاعلة", definition: "العلة الفاعلة (Cause efficiente) — المصدر المباشر الذي يُحدث الحركة أو التغير أو الوجود." },
    { term: "الذات / الأنا", definition: "الأنا (Moi / Ego) — الذات الواعية بوصفها مركز التجربة النفسية والهوية الشخصية، أو الأنا في التحليل النفسي الفرويدي (بين الهو والأنا الأعلى)." },
    { term: "الأنانية", definition: "الأنانية (Égoïsme) — النزعة التي تجعل المصلحة الذاتية واللذة الشخصية غاية وحيدة للسلوك وتُقصي مصالح الغير." },
    { term: "الإيغولوجيا", definition: "الإيغولوجيا (Égologie) — الدراسة الفلسفية للأنا والوعي الذاتي وبنيته." },
    { term: "الاندفاع الحيوي", definition: "الاندفاع الحيوي (Élan vital) — القوة الخلاقة الأصلية والمستمرة التي تدفع مسار التطور الحيوي وتبدع أشكالاً جديدة (عند هنري برغسون)." },
    { term: "العنصر / الأساس الأولي", definition: "العنصر (Élément) — الجزء البسيط الذي يدخل في تركيب الأشياء أو المبادئ الأولية التي يتأسس عليها علم أو نسق." },
    { term: "التحرر / الانعتاق", definition: "الانعتاق (Émancipation) — خروج الفرد أو الجماعة من حالة القصور أو التبعية أو الاستغلال نحو الاستقلال والحرية." },
    { term: "الظهور / البروز", definition: "البروز / الانبثاق (Émergence) — ظهور خصائص أو مستويات تنظيمية جديدة في كل مركب لا يمكن التنبؤ بها أو ردها كلياً إلى خصائص أجزائه المنفصلة." },
    { term: "الفيض / الصدور", definition: "الفيض (Émanation) — النظرية الميتافيزيقية (خاصة في الأفلاطونية المحدثة) التي تفسر صدور الكثرة عن الواحد المتعالي دون نقص أو إرادة صنع." },
    { term: "الانفعال العاطفي", definition: "الانفعال (Émotion) — اضطراب وجداني مفاجئ ومكثف يصحبه تغير فيزيولوجي واضح (كالخوف والغضب والفرح)." },
    { term: "التجريبية", definition: "التجريبية (Empirisme) — المذهب المعرفي القائل بأن التجربة الحسية هي المصدر الأول والأساسي لكل معرفة أو فكرة (مثل لوك وهيوم)." },
    { term: "التجريبي", definition: "التجريبي (Empirique) — ما يستند إلى الملاحظة والتجربة الحسية لا إلى الاستدلال العقلي الخالص أو المبادئ القبلية." },
    { term: "الطاقة", definition: "الطاقة (Énergie) — القدرة الكامنة أو الفعلية على إنجاز شغل أو إحداث تغير فيزيائي أو نفسي." },
    { term: "الشيء في ذاته", definition: "الشيء في ذاته (En soi) — وجود الشيء مستقلاً عن شروط إدراك الذات ووعيها (عند كانط)، أو الوجود المكتفي بذاته والمغلق على ذاته (عند سارتر)." },
    { term: "المعرفة الموسوعية", definition: "الموسوعية (Encyclopédisme) — النزعة إلى جمع وتنظيم وتعميم المعارف الإنسانية في نسق شامل لخدمة العقل والتقدم (فلسفة الأنوار)." },
    { term: "الفضاء / الامتداد", definition: "الامتداد (Étendue) — الخاصية الجوهرية للمادة عند ديكارت والمتمثلة في الطول والعرض والعمق وشغل حيز مكاني." },
    { term: "الأخلاق", definition: "الأخلاق (Éthique) — المبحث الفلسفي الذي يدرس أسس السلوك القويم ومعايير الخير والواجب والفضيلة (وتُستعمل أحياناً مرادفة للأخلاق العملية Morale أو مميزة عنها)." },
    { term: "الماهية / الجوهر", definition: "الماهية (Essence) — ما به يكون الشيء ما هو عليه، أي حقيقته الثابتة ومجموع مقوماته الضرورية في مقابل وجوده الفعلي أو أعراضه." },
    { term: "الجوهرية", definition: "الجوهرية (Essentialisme) — المذهب الفلسفي القائل بأن للشيء ماهية أو طبيعة ثابتة سابقة على وجوده أو محددة لهويته (في مقابل الوجودية)." },
    { term: "الوجود / الكينونة", definition: "الوجود (Existence) — التحقق الفعلي والواقعي للشيء، ويكتسب معنى خاصاً في الوجودية حيث يسبق وجود الإنسان ماهيته التي يصنعها بحريته." },
    { term: "الوجودية", definition: "الوجودية (Existentialisme) — تيار فلسفي يركز على الوجود الفردي الملموس للإنسان وحريته ومسؤوليته وقلقه في عالم لا يمتلك معنى جاهزاً مسبقاً." },
    { term: "الخبرة / التجربة", definition: "الخبرة (Expérience) — الممارسة الحية أو الملاحظة المنظمة التي يتفاعل عبرها الوعي مع الواقع وتنتج المعرفة." },
    { term: "التجريب", definition: "التجريب (Expérimentation) — تدخل الباحث المنظم لتعديل شروط الظاهرة وعزل المتغيرات للتحقق من الفرضيات العلمية." },
    { term: "التفسير", definition: "التفسير (Explication) — الكشف عن العلل أو القوانين أو المبادئ التي تجعل ظاهرة ما مفهومة وضرورية." },
    { term: "التعبير", definition: "التعبير (Expression) — إخراج المعنى أو الحالة الباطنية أو الدلالة إلى صورة حسية أو رمزية أو لغوية." },
    { term: "الاستقراء", definition: "الاستقراء (Induction / Énumération) — الانتقال المنطقي من ملاحظة حالات أو وقائع جزئية إلى استخلاص قاعدة أو قانون كلي." },
    { term: "الخطأ", definition: "الخطأ (Erreur) — حكم غير مطابق للواقع أو للقواعد المنطقية، وينشأ عند ديكارت من مجاوزة الإرادة لحدود الإدراك الواضح والمتميز." },
    { term: "المساواة", definition: "المساواة (Égalité) — المبدأ الحقوقي والسياسي والأخلاقي القاضي بتكافؤ الأفراد في الحقوق أو الكرامة أو المعاملة أمام القانون." },
    { term: "الإبستمولوجيا", definition: "الإبستمولوجيا (Épistémologie) — الدراسة النقدية لأسس العلوم ومناهجها ومفاهيمها ونتائجها لتقييم قيمتها المعرفية." },

    // ==========================================
    // --- حرف F (الدفعة الثالثة من الكتاب الأول) ---
    // ==========================================
    { term: "الواقعة / الحقيقة الواقعية", definition: "الواقعة (Fait) — معطى تجريبي أو حدث متحقق في الواقع يمكن التحقق منه بالملاحظة أو الشهادة في مقابل الفرض أو القيمة." },
    { term: "الواقعية التجريبية", definition: "الواقعية التجريبية (Faitisme) — النزعة التي تقصر البحث على الوقائع المباشرة وتتحفظ إزاء التعميمات النظرية أو الميتافيزيقية." },
    { term: "الملكة / القدرة", definition: "الملكة (Faculté) — القوة أو الاستعداد الثابت في النفس لممارسة نشاط معين كالإدراك أو الذاكرة أو التفكير أو الإرادة." },
    { term: "المغالطة", definition: "المغالطة (Fallacie) — خطأ في الاستدلال أو حجة خادعة تبدو متماسكة ظاهرياً لكنها تنطوي على خلل منطقي أو مغالطة لفظية." },
    { term: "الأسرة / العائلة", definition: "الأسرة (Famille) — الجماعة الأولية القائمة على روابط الدم أو المصاهرة أو التبني، ولها دور أساسي في التنشئة الاجتماعية والأخلاقية." },
    { term: "الخيال الوهمي / الفانتازم", definition: "الفانتازم (Fantasme) — صورة أو سيناريو تخيلي يعبّر عن رغبة أو لاوعي يبتعد عن الواقع المادي المباشر." },
    { term: "القدرية / الحتمية المطلقة", definition: "القدرية (Fatalisme) — الاعتقاد بأن الأحداث والمصائر مقررة سلفاً بقوة قاهرة أو قدر لا راد له، مما يجعل الإرادة والجهد البشري بلا أثر." },
    { term: "المصير / القدر المحتوم", definition: "القدر (Fatalité) — الضرورة الصارمة أو القوة المهيمنة التي تحكم مجرى الأمور خارج إرادة الفاعل." },
    { term: "الخصوبة المعرفية", definition: "الخصوبة (Fécondité) — قدرة المفهوم أو الفرضية أو المنهج على توليد نتائج جديدة وتفتح آفاق بحثية إضافية." },
    { term: "الوفاء / الإخلاص", definition: "الوفاء (Fidélité) — الثبات على العهد والالتزام الأخلاقي والوجداني تجاه الأشخاص أو المبادئ عبر الزمن." },
    { term: "الغائية", definition: "الغائية (Finalisme) — المذهب القائل بأن الكون أو الكائنات الحية أو الأفعال الإنسانية محكومة بغايات وأهداف لا بمجرد علل ميكانيكية سابقة." },
    { term: "الغاية", definition: "الغاية (Fin) — الهدف أو المقصد الذي يتجه إليه الفعل ويمنحه معناه؛ وقد تكون غاية جزئية أو غاية في ذاتها (كما في الإنسان عند كانط)." },
    { term: "المتناهي", definition: "المتناهي (Fini) — ما له حد أو نهاية في الكم أو الوجود أو القدرة، في مقابل اللامتناهي (Infini)." },
    { term: "الصورة / الشكل", definition: "الصورة / الشكل (Forme) — البنية أو النظام الذي يحدد المادة ويمنح الشيء صورته الخاصة (عند أرسطو)، أو الإطار القبلي المنظم للمعرفة (عند كانط)." },
    { term: "الصورية / الشكلانية", definition: "الصورية (Formalisme) — الاتجاه الذي يولي اهتماماً أساسياً للبنية الشكلية أو القواعد الصورية المجردة، كما في المنطق الصوري أو الأخلاق الصورية الكانطية." },
    { term: "الأساس / المسوّغ", definition: "الأساس (Fondement) — المبدأ أو البرهان أو السبب الجذري الذي يستند إليه صدق قضية أو مشروعية حكم أو قاعدة." },
    { term: "القوة", definition: "القوة (Force) — القدرة على الفعل أو إحداث حركة أو مقاومة أو فرض تأثير مادي أو معنوي." },
    { term: "الحرية", definition: "الحرية (Liberté) — قدرة الفاعل على الفعل أو الامتناع عنه من تلقاء ذاته وبوعي دون إكراه خارجي أو استعباد داخلي." },
    { term: "الوظيفة", definition: "الوظيفة (Fonction) — الدور المحدد الذي يؤديه عنصر أو عضو أو مؤسسة للحفاظ على توازن الكل واستمراره، أو علاقة التبعية الرياضية بين متغيرين." },
    { term: "الوظيفية", definition: "الوظيفية (Fonctionnalisme) — المنهج الذي يفسر الظواهر النفسية أو الاجتماعية أو البيولوجية من خلال وظائفها وأدوارها داخل النسق الكلي." },
    { term: "الوظيف / الموظف", definition: "الوظيفة الاجتماعية (Fonction sociale) — المهمة أو المكانة المحددة التي يشغلها الفرد أو الفئة داخل تقسيم العمل الاجتماعي." },
    { term: "المستقبل", definition: "المستقبل (Futur) — البعد الزمني الآتي الذي لم يتحقق بعد في الحاضر، وهو مجال المشروع والإمكان والترقب." },
    
    // ==========================================
    // --- حرف G (الدفعة الرابعة من الكتاب الأول) ---
    // ==========================================
    { term: "المقياس / المقدار", definition: "المقدار (Grandeur) — كل ما يقبل الزيادة والنقصان أو القياس الكمي المتصل أو المنفصل." },
    { term: "العموم / الكلية", definition: "العموم (Généralité) — صفة المفهوم أو الحكم الصادق على عدد كبير من الأفراد أو الحالات المشتركة في خاصية معينة." },
    { term: "التعميم", definition: "التعميم (Généralisation) — العملية العقلية التي يتم من خلالها توسيع نطاق حكم أو قانون من حالات جزئية ملاحظة إلى فئة أوسع أو إلى الكل." },
    { term: "النشأة / التكوين", definition: "النشأة / التكوين (Genèse) — المسار التكويني أو التاريخي أو المنطقي الذي يظهر ويتطور من خلاله الشيء أو المفهوم أو البنية المعرفية." },
    { term: "التكوينية (المنهج التكويني)", definition: "المنهج التكويني (Méthode génétique) — دراسة الظاهرة أو الفكرة أو الملكة النفسية عبر تتبع مراحل نشأتها وتطورها التاريخي أو النمائي." },
    { term: "العبقرية", definition: "العبقرية (Génie) — الاستعداد الفطري الاستثنائي الذي يمكّن المبدع من إنتاج أعمال أصيلة تتجاوز القواعد المألوفة دون أن تكون مجرد تقليد أو تطبيق آلي لقواعد مسبقة (عند كانط)." },
    { term: "الجنس المنطقي", definition: "الجنس (Genre) — المفهوم الكلي الأوسع الذي يشمل تحته نوعين أو أكثر ويُضاف إليه الفصل النوعي لتحديد الماهية في المنطق الأرسطي." },
    { term: "الجغرافيا الإنسانية / الفلسفية", definition: "الجغرافيا الإنسانية (Géographie humaine) — دراسة العلاقة المتبادلة بين الوسط الجغرافي والطبيعي وبين المجتمعات الإنسانية وتطورها الثقافي." },
    { term: "الهندسة", definition: "الهندسة (Géométrie) — العلم الرياضي الذي يدرس المكان والأشكال والأبعاد، وله دور محوري في تاريخ الفلسفة بين النسق الإقليدي والهندسات اللاإقليدية." },
    { term: "الإيماءة", definition: "الإيماءة (Geste) — حركة جسدية أو تعبيرية ذات دلالة نفسية أو تواصلية أو رمزية." },
    { term: "الذوق الجمالي", definition: "الذوق (Goût) — الملكة أو الاستعداد الذي يُمكّن من الحكم على الجمال والقبح واستحسان الجميل أو استقباحه (مبحث أساسي في جماليات كانط)." },
    { term: "الجاذبية", definition: "الجاذبية (Gravitation) — القوة الفيزيائية الشاملة التي تتجاذب بها الأجسام ذات الكتلة في الفضاء وفق قانون نيوتن، وقد أثارت نقاشات فلسفية حول طبيعة الفعل عن بُعد والآلية." },
    { term: "المجاني / غير النفعي", definition: "المجاني (Gratuit) — ما يقوم بذاته دون غاية نفعية مباشرة أو مقابل مادي، مثل اللعب أو التأمل الجمالي أو الفعل الخالص." },
    { term: "الامتنان / الشكر", definition: "الامتنان (Gratitude) — الشعور الأخلاقي والوجداني بالاعتراف بالجميل تجاه من أسدى خيراً أو معروفاً." },
    { term: "المجموعة / الجمع", definition: "المجموعة (Groupe) — اجتماع عناصر أو أفراد تجمعهم رابطة أو خاصية مشتركة، وللمفهوم دلالة دقيقة في الرياضيات والمنطق وعلم الاجتماع." },
    { term: "الجمهور / العامة", definition: "الجمهور (Public / Gens) — تجمع الأفراد أو الرأي العام الذي يتلقى الأفكار والأعمال أو يتفاعل معها دون تنظيم مؤسسي صارم." },
    { term: "النمو", definition: "النمو (Croissance) — الزيادة الكمية أو التطور العضوي التدريجي للكائن الحي أو البنية عبر الزمن." },

    // ==========================================
    // --- حرف H (الدفعة الرابعة من الكتاب الأول) ---
    // ==========================================
    { term: "العادة", definition: "العادة (Habitude) — استعداد مكتسب وثابت نسبياً ينشأ عن تكرار الفعل، ويجعل أداءه أسهل وأكثر تلقائية وآلية، ولها دور مزدوج في تقوية الإرادة أو تقييدها." },
    { term: "الهيرمينوطيقا / التأويل", definition: "الهيرمينوطيقا (Herméneutique) — فن وعلم فهم وتأويل النصوص والرموز واستخراج معانيها الضمنية أو السياقية." },
    { term: "التاريخ", definition: "التاريخ (Histoire) — مجرى الأحداث والوقائع الإنسانية في الزمان، وكذلك العلم الذي يدرس الماضي الإنساني ويفسر تحولاته." },
    { term: "التاريخانية", definition: "التاريخانية (Historisme) — المذهب الذي يرى أن الظواهر الإنسانية والقيم والمعارف والمؤسسات مشروطة تاريخياً ولا تفهم إلا في سياق تطورها التاريخي." },
    { term: "فلسفة التاريخ", definition: "فلسفة التاريخ (Philosophie de l'histoire) — التأمل الفلسفي في معنى مسار التاريخ الإنساني وقوانينه وغاياته المحتملة." },
    { term: "الإنسان", definition: "الإنسان (Homme) — الكائن العاقل والاجتماعي والحر الذي يمثل موضوع الأنثروبولوجيا والأخلاق والسياسة والميتافيزيقيا." },
    { term: "الإنسانية / النزعة الإنسانية", definition: "الإنسانية (Humanisme) — الموقف الفكري والثقافي الذي يجعل الإنسان وقيمه وحريته وكرامته مركز الاهتمام والتقدير." },
    { term: "الفرضية", definition: "الفرضية (Hypothèse) — افتراض أو تفسير مؤقت يُصاغ لتوجيه البحث والتحقق التجريبي أو الاستدلالي من صحته أو بطلانه." },
    { term: "الهيلومورفية", definition: "الهيلومورفية (Hylémorphisme) — النظرية الأرسطية القائلة بأن كل جسم طبيعي مركب من مبدأين متلازمين هما المادة (Hylê) والصورة (Morphê)." },
    { term: "الأقنوم / الجوهر المفرد المتعين", definition: "الأقنوم / الهيبوستاز (Hypostase) — الجوهر القائم بذاته أو تعيّن مبدأ مجرد في صورة كيان مستقل." },
    { term: "الهستيريا", definition: "الهستيريا (Hystérie) — حالة نفسية وعصبية تتجلى في أعراض جسدية أو انفعالية دون علة عضوية مباشرة، وقد أسهمت دراستها في تطور علم النفس المرضي والتحليل النفسي." },
    { term: "المتجانس", definition: "المتجانس (Homogène) — ما تتشابه أجزاؤه أو عناصره في الطبيعة أو النوع أو التركيب." },
    { term: "التجانس", definition: "التجانس (Homogénéité) — تماثل الخصائص أو العناصر داخل كلّ أو وسط معين." },
    { term: "المذهب اللذتي / الهيدونية", definition: "الهيدونية (Hédonisme) — المذهب الأخلاقي الذي يرى أن اللذة هي الخير الأسمى والغاية الأساسية للسلوك الإنساني." },

    // ==========================================
    // --- حرف I (الدفعة الرابعة من الكتاب الأول) ---
    // ==========================================
    { term: "الفكرة", definition: "الفكرة (Idée) — التصور العقلي أو الصورة الذهنية أو الماهية المعقولة؛ وتتباين دلالتها من المثل المفارقة عند أفلاطون إلى الأفكار الواضحة والمتميزة عند ديكارت وإلى مقولات أو أفكار العقل عند كانط." },
    { term: "المثالية", definition: "المثالية (Idéalisme) — المذهب الفلسفي الذي يرى أن الفكر أو الوعي أو المبادئ المثالية لها الأولوية أو الأساس في تحديد الواقع والمعرفة." },
    { term: "المثالية المتعالية", definition: "المثالية المتعالية (Idéalisme transcendantal) — مذهب كانط القائل بأن الظواهر المكانية والزمانية مشروطة ببنى الذات العارفة القبلية، مع الإبقاء على فكرة الشيء في ذاته." },
    { term: "المثال", definition: "المثال (Idéal) — النموذج الأسمى أو الكمال المعياري الذي يوجه السعي الأخلاقي أو الجمالي أو العقلي دون أن يتحقق بصورة مطلقة في الواقع التجريبي." },
    { term: "الهوية", definition: "الهوية (Identité) — تطابق الشيء مع ذاته وبقاؤه هو هو (مبدأ الهوية في المنطق)، وكذلك استمرار الذات الشخصية عبر تغير حالاتها وأزمنتها." },
    { term: "مبدأ الهوية", definition: "مبدأ الهوية (Principe d'identité) — المبدأ المنطقي الأساسي القائل بأن كل شيء هو ذاته (أ هو أ)." },
    { term: "الإيديولوجيا", definition: "الإيديولوجيا (Idéologie) — نسق من الأفكار والمعتقدات والقيم التي توجه السلوك الاجتماعي أو السياسي أو تعبر عن مصالح أو أوضاع جماعة معينة." },
    { term: "الخيال", definition: "الخيال (Imagination) — القدرة النفسية على استحضار صور الأشياء غير الحاضرة أو تركيب صور جديدة؛ وقد يكون خيالاً reproductif (استرجاعياً) أو créateur (إبداعياً)." },
    { term: "المحاكاة", definition: "المحاكاة (Imitation) — تقليد نموذج أو طبيعة أو سلوك، ولها مكانة مركزية في نظرية الفن عند أفلاطون وأرسطو وفي علم النفس الاجتماعي." },
    { term: "المحايثة", definition: "المحايثة (Immanence) — كون المبدأ أو العلة أو الفاعلية قائمة في داخل الشيء أو الوعي نفسه لا خارجه ولا مفارقة له (مقابل التعالي Transcendance)." },
    { term: "اللامادي", definition: "اللامادي (Immatériel) — ما لا يتألف من مادة ولا يشغل حيزاً مكانياً، كالروح والفكر والمفاهيم المجردة." },
    { term: "الاستدلال", definition: "الاستدلال (Inférence) — الانتقال العقلي المنظم من قضية أو قضايا مقبولة (مقدمات) إلى قضية أخرى (نتيجة) ترتبط بها منطقياً." },
    { term: "اللامتناهي", definition: "اللامتناهي (Infini) — ما لا نهاية له ولا حدّ يحيط به في الكم أو الامتداد أو الكمال، ويُدرس في الرياضيات واللاهوت والميتافيزيقيا." },
    { term: "الفطري", definition: "الفطري (Inné) — ما يكون حاضراً في النفس أو العقل منذ الأصل ولا يُكتسب عن طريق التجربة الحسية (مثل الأفكار الفطرية عند ديكارت)." },
    { term: "الفطرية", definition: "الفطرية (Innéisme) — المذهب القائل بوجود أفكار أو مبادئ أولية فطرية في العقل سابقة على التجربة." },
    { term: "الابتكار / الاختراع", definition: "الابتكار (Invention) — إبداع فكرة أو منهج أو أداة أو حل جديد لم يكن معروفاً من قبل." },
    { term: "الذكاء", definition: "الذكاء (Intelligence) — القدرة العقلية على الفهم، والربط بين العلاقات، والتكيف المرن مع المواقف الجديدة وحل المشكلات." },
    { term: "الحدس", definition: "الحدس (Intuition) — الإدراك المباشر والفوري للحقيقة دون وساطة استدلالية طويلة (حدس عقلي أو حسي أو فلسفي كما عند برغسون)." },
    { term: "الغريزة", definition: "الغريزة (Instinct) — نزعة سلوكية فطرية موروثة ومعقدة نسبياً، موجهة نحو غاية حيوية دون حاجة إلى تعلم سابق أو تفكير نظري." },
    { term: "اللاوعي", definition: "اللاوعي (Inconscient) — مجموع الظواهر أو الدوافع أو الخبرات النفسية التي تقع خارج الوعي المباشر ولكنها تؤثر في السلوك والحياة النفسية." },
    { term: "المفارقة / التناقض الظاهري", definition: "المفارقة (Paradoxe / Incohérence apparente) — قضية أو حالة تبدو مخالفة للرأي الشائع أو للبداهة العادية، وقد تكشف عن حقيقة أعمق أو إشكال منطقي." },
    
    // ==========================================
    // --- حرف J (الدفعة الخامسة من الكتاب الأول) ---
    // ==========================================
    { term: "الحكم", definition: "الحكم (Jugement) — الفعل العقلي الذي يربط بين موضوع ومحمول أو يقرّ صدق قضية أو كذبها؛ وهو الوحدة الأساسية للمعرفة عند كانط." },
    { term: "الحكم التأليفي / التركيبي", definition: "الحكم التركيبي (Jugement synthétique) — حكم يضيف فيه المحمول صفة أو معرفة جديدة إلى مفهوم الموضوع لا تتضمنها ماهية الموضوع ابتداءً (عند كانط)." },
    { term: "الحكم التحليلي", definition: "الحكم التحليلي (Jugement analytique) — حكم يكون فيه المحمول مستخرجاً أو متضمناً في مفهوم الموضوع ذاته ولا يوسّع المعرفة الجديدة (عند كانط)." },
    { term: "حكم القيمة", definition: "حكم القيمة (Jugement de valeur) — حكم يقدّر الشيء أو الفعل من حيث قيمته الأخلاقية أو الجمالية أو النفعية، في مقابل حكم الواقع الذي يصف ما هو كائن." },
    { term: "حكم الواقع", definition: "حكم الواقع (Jugement de réalité / de fait) — حكم يقرر واقعاً أو علاقة تجريبية أو منطقية كما هي قائمة دون إصدار تقدير قيمي." },
    { term: "العدالة", definition: "العدالة (Justice) — الفضيلة والمبدأ الأخلاقي والسياسي المتمثل في إعطاء كل ذي حق حقه، وتحقيق التوازن والإنصاف بين الحقوق والواجبات في المجتمع." },
    { term: "العدالة التوزيعية", definition: "العدالة التوزيعية (Justice distributive) — توزيع الخيرات والمنافع والأعباء والمناصب وفق معيار الاستحقاق أو الحاجة أو المساواة (منذ أرسطو)." },
    { term: "العدالة التبادلية / التعويضية", definition: "العدالة التبادلية (Justice commutative) — إنصاف المعاملات والتبادلات التعاقدية وتعويض الضرر بما يماثله." },
    { term: "التبرير", definition: "التبرير (Justification) — تقديم الأدلة أو الأسباب أو المبادئ المسوِّغة لصحة حكم أو شرعية فعل أو اعتقاد." },
    { term: "الشباب", definition: "الشباب (Jeunesse) — المرحلة العمرية والحيوية التي تتسم بالمرونة والانفتاح على التجربة وتشكيل الهوية والمشروع الحياتي." },
    { term: "اللعب", definition: "اللعب (Jeu) — نشاط حر وتلقائي يُمارس لذاته غالباً خارج الإكراه النفعي المباشر، وله أدوار نفسية وتربوية وجمالية (كما عند شيلر)." },

    // ==========================================
    // --- حرف K (الدفعة الخامسة من الكتاب الأول) ---
    // ==========================================
    { term: "الكانطية", definition: "الكانطية (Kantisme) — المذهب الفلسفي النقدي لإيمانويل كانط، القائم على تحليل شروط إمكان المعرفة العلمية والأخلاقية والجمالية والتمييز بين الظاهرة والشيء في ذاته." },
    { term: "الكانتية الجديدة", definition: "الكانتية الجديدة (Néo-kantisme) — تيار فلسفي نشأ في النصف الثاني من القرن التاسع عشر وسعى إلى تجديد الفلسفة النقدية والتركيز على الإبستمولوجيا ونظرية القيم." },
    { term: "القبالة / الكابالا", definition: "الكابالا (Kabbale) — منظومة باطنية وصوفية قائمة على التأويل الرمزي والعددي للنصوص، ولها حضور تاريخي في الفكر الوسيط وعصر النهضة." },
    { term: "الكليبسيس / الكسوف الفلسفي", definition: "الكليبسيس / الاحتجاب (Éclipse) — تواري أو خفوت أثر مبدأ أو قيمة أو نمط تفكير في مرحلة تاريخية معينة." },

    // ==========================================
    // --- حرف L (الدفعة الخامسة من الكتاب الأول) ---
    // ==========================================
    { term: "اللغة", definition: "اللغة (Langage) — القدرة أو النظام الرمزي العام الذي يتيح التواصل والتعبير عن الأفكار والانفعالات عبر الإشارات والأصوات والرموز." },
    { term: "اللسان / اللغة الخاصة", definition: "اللسان (Langue) — المنظومة المؤسسية والاجتماعية المنظمة من القواعد والرموز المشتركة بين أفراد جماعة لغوية معينة (وفق التمييز السوسيري)." },
    { term: "اللفظ / المصطلح", definition: "اللفظ / المصطلح (Terme / Mot) — الوحدة اللغوية الدالة على معنى محدد أو مفهوم في سياق عادي أو تقني." },
    { term: "القانون", definition: "القانون (Loi) — قاعدة عامة وثابتة تنظم العلاقات؛ وهو في الطبيعة علاقة ضرورية مطردة بين الظواهر، وفي المجتمع قاعدة ملزمة ينظمها التشريع أو العرف." },
    { term: "قانون الطبيعة", definition: "قانون الطبيعة (Loi naturelle) — العلاقة الثابتة والقابلة للتحقق التي تربط بين الظواهر الفيزيائية أو البيولوجية في شروط محددة." },
    { term: "القانون الأخلاقي", definition: "القانون الأخلاقي (Loi morale) — المبدأ العملي الكوني الملزم الذي تشرّعه الإرادة العاقلة لنفسها وتلزم به ذاتها (عند كانط)." },
    { term: "الحرية", definition: "الحرية (Liberté) — قدرة الفاعل على الفعل أو الامتناع عنه من تلقاء ذاته ووفق إرادته وعقله دون إكراه خارجي أو استعباد داخلي." },
    { term: "الحرية السلبية والحرية الإيجابية", definition: "الحرية السلبية والإيجابية (Liberté négative / positive) — التمييز بين التحرر من العوائق الخارجية والإكراه وبين القدرة الفعلية على التقرير الذاتي وتحقيق الغايات." },
    { term: "الليبرالية", definition: "الليبرالية (Libéralisme) — التوجه الفكري والسياسي والاقتصادي الذي يجعل من حرية الفرد وحقوقه الأساسية والكرامة الشخصية مرتكزاً أساسياً للنظام الاجتماعي." },
    { term: "المنطق", definition: "المنطق (Logique) — العلم الذي يدرس قوانين وشروط الفكر الصحيح والاتساق الصوري أو الاستدلالي." },
    { term: "المنطق الصوري", definition: "المنطق الصوري (Logique formelle) — دراسة صحة الاستدلال وصورته المنطقية بغض النظر عن مضمونه المادي الواقعي." },
    { term: "المنطق المتعالي", definition: "المنطق المتعالي (Logique transcendantale) — دراسة القوانين والمقولات القبلية للفهم التي تجعل معرفة الموضوعات التجريبية ممكنة (عند كانط)." },
    { term: "اللوغوس", definition: "اللوغوس (Logos) — مفهوم يوناني أصيل يجمع بين العقل، النظام الكوني، الكلمة، والخطاب المنظم الذي يمنح العالم والمعرفة معقوليتهما." },
    { term: "الحدّ / النهاية", definition: "الحدّ (Limite) — النقطة أو الخط أو الشرط الذي ينتهي عنده الشيء أو يبدأ عنده شيء آخر، أو الحد المعرفي الذي لا يتجاوزه العقل دون الوقوع في الغموض أو التناقض." },
    { term: "الضوء / النور العقلي", definition: "النور (Lumière) — استعارة فلسفية وعرفانية مركزية ترمز إلى وضوح العقل والبداهة والحقيقة أو الإشراق المعرفي (كما في الأنوار والإشراقية)." },
    { term: "الترف / الفخامة", definition: "الترف (Luxe) — إنفاق الموارد فيما يتجاوز الحاجات الضرورية للمعيشة، وله دلالات اقتصادية وأخلاقية ونقدية في الفلسفة الاجتماعية." },

    // ==========================================
    // --- حرف M (الدفعة الخامسة من الكتاب الأول) ---
    // ==========================================
    { term: "المادة", definition: "المادة (Matière) — ما يشغل حيزاً مكانياً وله كتلة في الفيزياء، أو المبدأ الأول القابل لتلقي الصور والتحولات (الهيولى عند أرسطو)، أو المضمون الحسي في مقابل الصورة." },
    { term: "المادية", definition: "المادية (Matérialisme) — المذهب الفلسفي الذي يرد أصل الوجود أو تفسيره الأساسي إلى المادة وحركتها وقوانينها، ويرى أن الظواهر النفسية والاجتماعية مرتبطة بالبنية المادية." },
    { term: "المادية التاريخية", definition: "المادية التاريخية (Matérialisme historique) — المنهج الماركسي الذي يفسر تطور المجتمعات والتاريخ عبر قوى الإنتاج وعلاقات الإنتاج والبنية الاقتصادية." },
    { term: "الآلية / الميكانيكية", definition: "الميكانيكية (Mécanisme) — التفسير الذي يرد ظواهر الطبيعة والحياة إلى قوانين الحركة والمكان والاتصال الفيزيائي المباشر دون اللجوء إلى غائية أو قوى خفية." },
    { term: "الذاكرة", definition: "الذاكرة (Mémoire) — القدرة النفسية على الاحتفاظ بالخبرات والصور الماضية واسترجاعها والتعرف عليها بوصفها ماضياً." },
    { term: "الوساطة", definition: "الوساطة (Médiation) — العملية أو العنصر الرابط الذي يصل بين طرفين أو مرحلتين أو مفهومين، ولها دور حاسم في المنطق والجدل الهيجلي." },
    { term: "الميتافيزيقيا", definition: "الميتافيزيقيا (Métaphysique) — المبحث الفلسفي الذي يتناول المبادئ الأولى والعلل القصوى للوجود، والجوهر، والحرية، واللامتناهي، وما يتجاوز التجربة الحسية المباشرة." },
    { term: "المنهج", definition: "المنهج (Méthode) — مجموعة من القواعد والخطوات المنظمة والمضبوطة التي يتبعها العقل لبلوغ الحقيقة أو حل إشكال علمي أو فلسفي." },
    { term: "المنهجية", definition: "المنهجية (Méthodologie) — دراسة المناهج المستعملة في العلوم المختلفة، وتحليل أسسها وحدودها وشروط صلاحيتها." },
    { term: "المعجزة", definition: "المعجزة (Miracle) — حدث خارق للسير المعتاد لقوانين الطبيعة يُنسب إلى قدرة إلهية مباشرة، وتُناقش في فلسفة الدين والسببية." },
    { term: "النموذج", definition: "النموذج (Modèle) — بنية أو صورة أو تمثيل نظري يُعتمد كمرجع للتفسير أو المحاكاة أو القياس في العلوم والفلسفة والفن." },
    { term: "الاعتدال", definition: "الاعتدال (Modération) — الفضيلة السلوكية والعقلية المتمثلة في التوسط وضبط الأهواء وتجنب الإفراط والتفريط." },
    { term: "الحداثة", definition: "الحداثة (Modernité) — الفترة والموقف الفكري المرتبط بسيادة العقل النقدي، والاستقلال الذاتي، وتقدم العلوم، وتحول البنى الاجتماعية والسياسية." },
    { term: "الجزئي / المونادة", definition: "المونادة (Monade) — الجوهر البسيط غير القابل للتجزئة عند لايبنتز، والممتلك لفاعلية إدراكية ونزوعية داخل انسجام سابق." },
    { term: "الأحادية", definition: "الأحادية (Monisme) — المذهب الفلسفي الذي يرد الكثرة الظاهرة للوجود إلى مبدأ أو جوهر واحد فقط (سواء كان مادياً أو روحياً أو جوهراً واحداً كسبينوزا)." },
    { term: "الأخلاق العملية", definition: "الأخلاق العملية (Morale) — مجموع القواعد والمعايير والقيم التي توجه السلوك الإنساني وتحدد ما ينبغي فعله وما يصح تجنبه." },
    { term: "الموت", definition: "الموت (Mort) — الانقطاع النهائي للحياة العضوية، وله أبعاد بيولوجية ونفسية ووجودية عميقة في تأمل معنى الوجود والفناء." },
    { term: "الدافع / الباعث", definition: "الدافع (Mobile / Motif) — العامل النفسي أو الشعوري أو العقلي الذي يحرك الإرادة ويوجه السلوك نحو فعل معين." },
    { term: "الحركة", definition: "الحركة (Mouvement) — كل تغير أو انتقال يطرأ على الشيء في المكان أو الكم أو الكيف أو الجوهر (كما حددها أرسطو في السماع الطبيعي)." },
    { term: "الأسطورة", definition: "الأسطورة (Mythe) — سرد رمزي تقليدي يعبّر عن تصورات جماعية لأصل الكون والنظام والمصير الإنساني، ويميزها الفكر الفلسفي غالباً عن اللوغوس والبرهان." },
    { term: "التصوف / العرفان", definition: "التصوف (Mysticisme) — الاتجاه الروحي الذي يسعى إلى معرفة الحقيقة المطلقة أو الاتحاد الروحي بها عبر التجربة الباطنية والحدس المباشر لا عبر الاستدلال العقلي وحده." }
];

// ============================================================
// 2. إعدادات Fuse.js
// ============================================================
const fuseOptions = {
    keys: ["term", "definition"],
    threshold: 0.4,
    includeMatches: true
};

const fuse = new Fuse(encyclopediaData, fuseOptions);

// ============================================================
// 3. ربط العناصر
// ============================================================
const searchInput = document.getElementById('searchInput');
const resultsContainer = document.getElementById('resultsContainer');
const resultCount = document.getElementById('resultCount');

// ============================================================
// 4. دالة عرض النتائج
// ============================================================
function renderResults(results, query) {
    resultsContainer.innerHTML = '';

    if (!query) {
        resultCount.textContent = '';
        resultsContainer.innerHTML = `<div class="empty-state">اكتب كلمة في صندوق البحث أعلاه لعرض النتائج</div>`;
        return;
    }

    if (results.length === 0) {
        resultCount.textContent = '';
        resultsContainer.innerHTML = `<div class="empty-state">😕 لا توجد نتائج مطابقة لـ «${query}»</div>`;
        return;
    }

    resultCount.textContent = `تم العثور على ${results.length} نتيجة`;

    results.forEach(result => {
        const item = result.item;

        const card = document.createElement('div');
        card.className = 'result-card';

        card.innerHTML = `
            <h3>${item.term}</h3>
            <div class="definition">${item.definition}</div>
        `;

        resultsContainer.appendChild(card);
    });
}

// ============================================================
// 5. البحث المباشر
// ============================================================
let debounceTimer;
searchInput.addEventListener('input', function(e) {
    clearTimeout(debounceTimer);
    const query = e.target.value;

    debounceTimer = setTimeout(() => {
        if (query.trim() === '') {
            renderResults([], '');
        } else {
            const results = fuse.search(query);
            renderResults(results, query);
        }
    }, 200);
});

// عرض الشاشة الأولى
renderResults([], '');
